function loadState(){try{const current=localStorage.getItem(STORE_KEY);const legacy=current===null?localStorage.getItem(LEGACY_STORE_KEY):null;const parsed=JSON.parse(current??legacy??"{}");const merged={...structuredClone(initialState),...parsed};if(!Array.isArray(merged.journal))merged.journal=[];if(!merged.costPlans||typeof merged.costPlans!=="object")merged.costPlans={};if(!merged.pathwayGroups||typeof merged.pathwayGroups!=="object")merged.pathwayGroups={};return merged}catch(e){return structuredClone(initialState)}}
function saveState(){try{const persisted=structuredClone(state);if(window.JALUR_API?.getUser?.())persisted.journal=[];localStorage.setItem(STORE_KEY,JSON.stringify(persisted));const user=window.JALUR_API?.getUser?.();if(user?.role==="student"&&window.JALUR_API?.request){const workspace={profile:state.profile,notes:state.notes,compared:state.compared,mainChoice:state.mainChoice,alternatives:state.alternatives,checked:state.checked,costPlans:state.costPlans,pathwayGroups:state.pathwayGroups,settings:state.settings};window.JALUR_WORKSPACE_PENDING=workspace;clearTimeout(window.JALUR_WORKSPACE_TIMER);window.JALUR_WORKSPACE_TIMER=setTimeout(()=>window.JALUR_API.request("/workspace",{method:"POST",body:{workspace}}).then(()=>{window.JALUR_WORKSPACE_PENDING=null}).catch(err=>toast(err.message||"Sinkronisasi ruang siswa gagal.","error")),500)}}catch(e){toast("Penyimpanan browser tidak tersedia; perubahan hanya ada di sesi ini.","error")}}
function logActivity(text){state.activities.unshift({text,time:new Date().toLocaleString("id-ID",{dateStyle:"medium",timeStyle:"short"})});state.activities=state.activities.slice(0,5);saveState()}
function toast(message,type="success"){const el=document.createElement("div");el.className=`toast ${type}`;el.textContent=message;$("#toastRegion").append(el);setTimeout(()=>el.remove(),5500)}
function escapeHtml(s=""){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
const PAGE_LABELS={"Dashboard":"Beranda","Academic Profile":"Profil Akademik","Study Program Explorer":"Penjelajah Program Studi","Study Tracer Alumni":"Pengalaman Alumni","Decision Comparison":"Perbandingan Program Studi","Plan B Builder":"Rencana Alternatif","Decision Blind Spot Detector":"Daftar Periksa Keputusan","Decision Summary":"Ringkasan Keputusan","Settings":"Pengaturan","Help / About":"Bantuan dan Tentang JALUR","User Guide":"Panduan Penggunaan","Official Sources":"Pusat Informasi Resmi","Program Study Reality Check":"Realitas Perkuliahan","Similarity Explorer":"Program Studi Serupa","Alternative Pathway Planner":"Peta Jalur Alternatif","Campus Life Preview":"Gambaran Kehidupan Kampus","Education Cost Planner":"Perencana Biaya Pendidikan","Decision Journal":"Jurnal Keputusan","BK Consultation":"Konsultasi BK","Anonymous Venting":"Curhat Anonim","School Portal":"Portal Pengelola Sekolah","BK Portal":"Portal Guru BK"};
function pageHead(title,desc,action=""){return `<div class="page-head"><div><span class="eyebrow">JALUR / PENDAMPING KEPUTUSAN</span><h1>${PAGE_LABELS[title]||title}</h1><p>${desc}</p></div>${action?`<div class="page-actions">${action}</div>`:""}</div>`}
function panel(title,content,sub="",actions=""){return `<section class="panel glass"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p class="panel-sub">${sub}</p>`:""}</div>${actions}</div>${content}</section>`}
function statCard(icon,label,value,hint,page){return `<button class="stat-card glass" data-page="${page}" style="text-align:left;width:100%;color:inherit"><div class="stat-top"><span class="stat-icon">${icon}</span><span class="stat-label">${label}</span></div><div class="stat-value">${value}</div><div class="stat-hint">${hint}</div></button>`}
function render(){ $("#pageCrumb").textContent=PAGE_LABELS[currentPage]||currentPage; $$("[data-page],.bottom-item[data-page],.nav-item[data-page]").forEach(b=>b.classList.toggle("active",b.dataset.page===currentPage));const primaryBottom=["Dashboard","Study Program Explorer","Decision Comparison","Plan B Builder"];$("#moreNav")?.classList.toggle("active",!primaryBottom.includes(currentPage));$("#profileAlert").style.display=state.profile.subjects.length?"none":"block"; const root=$("#pageRoot"); const renderers={"Dashboard":dashboardPage,"Academic Profile":profilePage,"Study Program Explorer":explorerPage,"Study Tracer Alumni":alumniPage,"Decision Comparison":comparisonPage,"Plan B Builder":planBPage,"Decision Blind Spot Detector":blindSpotPage,"Decision Summary":summaryPage,"Settings":settingsPage,"Help / About":helpPage,"User Guide":guidePage,"Official Sources":sourcesPage,"Program Study Reality Check":realityPage,"Similarity Explorer":similarityPage,"Alternative Pathway Planner":pathwayPage,"Campus Life Preview":campusPage,"Education Cost Planner":costPage,"Decision Journal":journalPage,"BK Consultation":consultationPage,"Anonymous Venting":ventingPage,"School Portal":schoolPortalPage,"BK Portal":bkPortalPage};root.innerHTML=(renderers[currentPage]||dashboardPage)();$("#main").focus({preventScroll:true});}
function gradeTrendChart(){
 const records=state.profile.subjects.filter(s=>Number.isFinite(Number(s.grade))&&Number(s.grade)>=0&&Number(s.grade)<=100);
 if(!records.length)return '';
 const groups=new Map();
 records.forEach(s=>{const year=String(s.year||'').trim(),semester=String(s.semester||'').trim(),key=year+'|'+semester;const g=groups.get(key)||{year,semester,sum:0,count:0};g.sum+=Number(s.grade);g.count++;groups.set(key,g)});
 const rows=[...groups.values()].map(g=>({...g,average:g.sum/g.count,yearOrder:Number((g.year.match(/\d{4}/)||[])[0])||0,semesterOrder:Number((g.semester.match(/\d+/)||[])[0])||0})).sort((a,b)=>a.yearOrder-b.yearOrder||a.semesterOrder-b.semesterOrder||alpha(a.year,b.year));
 const w=720,h=230,left=42,right=22,top=18,bottom=48,plotW=w-left-right,plotH=h-top-bottom;
 const x=i=>rows.length===1?left+plotW/2:left+(i/(rows.length-1))*plotW;
 const y=v=>top+((100-v)/100)*plotH;
 const pts=rows.map((r,i)=>({x:x(i),y:y(r.average),r}));
 const path=pts.map((p,i)=>(i?'L':'M')+p.x.toFixed(1)+' '+p.y.toFixed(1)).join(' ');
 const grid=[0,25,50,75,100].map(v=>'<g><line x1="'+left+'" y1="'+y(v)+'" x2="'+(w-right)+'" y2="'+y(v)+'" class="grade-chart-grid"/><text x="'+(left-10)+'" y="'+(y(v)+4)+'" text-anchor="end" class="grade-chart-axis">'+v+'</text></g>').join('');
 const labels=pts.map(p=>'<text x="'+p.x+'" y="'+(h-20)+'" text-anchor="middle" class="grade-chart-label">'+escapeHtml(p.r.semester.replace(/^Semester\s*/i,'S')+' · '+p.r.year)+'</text>').join('');
 const dots=pts.map(p=>'<circle cx="'+p.x+'" cy="'+p.y+'" r="5" class="grade-chart-point"><title>'+escapeHtml(p.r.semester+' '+p.r.year+': '+p.r.average.toFixed(1)+' ('+p.r.count+' mata pelajaran)')+'</title></circle>').join('');
 const first=rows[0].average,last=rows[rows.length-1].average,delta=last-first;
 const trend=rows.length<2?'Data baru mencakup satu semester. Tambahkan nilai dari semester lain untuk melihat perubahan.':(Math.abs(delta)<0.05?'Rata-rata stabil pada rentang semester yang tercatat.':(delta>0?'Naik ':'Turun ')+Math.abs(delta).toFixed(1)+' poin dibanding semester pertama yang tercatat.');
 return '<div class="grade-trend"><div class="grade-trend-meta"><strong>Rata-rata per semester</strong><span>'+rows.length+' periode · '+records.length+' nilai</span></div><svg class="grade-trend-svg" viewBox="0 0 '+w+' '+h+'" role="img" aria-label="Grafik rata-rata nilai per semester"><title>Tren rata-rata nilai akademik</title><desc>'+escapeHtml(trend)+'</desc>'+grid+(rows.length>1?'<path d="'+path+'" class="grade-chart-line"/>':'')+dots+labels+'</svg><p class="grade-trend-caption">'+escapeHtml(trend)+'</p><p class="source-line">Rata-rata dihitung dari nilai yang tersimpan untuk setiap semester dan tahun ajaran. Data Contoh tetap merupakan simulasi.</p></div>';
}
function dashboardPage(){
 const pct=Math.min(100,Math.round(state.profile.subjects.length/6*100));const checked=state.checked.length;
 const next=[];
 if(!state.profile.subjects.length)next.push(["♙","Lengkapi Academic Profile","Masukkan nilai agar ringkasan akademik tersedia.","Academic Profile"]);
 if(!state.compared.length)next.push(["⌕","Jelajahi program studi","Cari pilihan yang ingin Anda pertimbangkan.","Study Program Explorer"]);
 if(state.compared.length<2)next.push(["⇄","Bandingkan pilihan","Tambahkan minimal dua program untuk membandingkan.","Decision Comparison"]);
 if(!state.mainChoice)next.push(["⑂","Susun Plan B","Tentukan pilihan utama dan alternatif dengan alasan.","Plan B Builder"]);
 const acts=state.activities.length?state.activities.map(a=>`<div class="activity-item"><span class="activity-bullet"></span><div><strong>${escapeHtml(a.text)}</strong><small>${escapeHtml(a.time)}</small></div></div>`).join(""):`<div class="empty-state"><div class="empty-icon">◷</div><h3>Belum ada aktivitas</h3><p>Aktivitasmu akan muncul di sini saat Anda mulai menjelajah.</p></div>`;
 return `${pageHead("Dashboard","Lihat langkah yang sudah Anda jelajahi dan tentukan langkah berikutnya.")}<div class="stat-grid">${statCard("♙","Kelengkapan profil",pct+"%",state.profile.subjects.length+" mata pelajaran","Academic Profile")}${statCard("⇄","Program dibandingkan",state.compared.length,"Dari maksimal 4 program","Decision Comparison")}${statCard("◉","Aspek ditinjau",`${checked}/12`,"Blind Spot Detector","Decision Blind Spot Detector")}</div><div class="dashboard-grid"><div class="stack">${panel("Langkah berikutnya",`<div class="quick-list">${next.slice(0,3).map(n=>`<button class="quick-action" data-page="${n[3]}"><span class="quick-icon">${n[0]}</span><span><strong>${n[1]}</strong><small>${n[2]}</small></span><span class="quick-arrow">↗</span></button>`).join("")||`<div class="empty-state"><h3>Semua langkah awal sudah dimulai</h3><p>Lanjutkan meninjau informasi dan lengkapi ringkasan keputusanmu.</p><button class="btn secondary small" data-page="Decision Summary">Lihat ringkasan</button></div>`}`,"Rekomendasi berdasarkan data sesi saat ini.")}${panel("Jejak nilai akademik",state.profile.subjects.length?`${gradeTrendChart()}<div class="grade-summary-list">${state.profile.subjects.slice().sort((a,b)=>alpha(a.name,b.name)||alpha(a.semester,b.semester)).slice(-8).map(s=>`<div class="progress-row"><label>${escapeHtml(s.name)} <span class="muted">· ${escapeHtml(s.semester)}</span></label><strong>${Number(s.grade).toLocaleString("id-ID")}</strong><div class="progress-track"><div class="progress-fill" style="width:${Math.max(0,Math.min(100,Number(s.grade)||0))}%"></div></div></div>`).join("")}</div><p class="source-line">Visualisasi hanya menggunakan nilai yang Anda masukkan. Tidak ada nilai pembanding buatan.</p>`:`<div class="empty-state"><div class="empty-icon">⌁</div><h3>Profil akademik belum diisi</h3><p>Masukkan nilai atau gunakan Data Contoh untuk melihat ringkasan akademik. Nilai adalah salah satu bahan pertimbangan, bukan penentu pilihan Anda.</p><button class="btn primary small" data-page="Academic Profile">Isi Academic Profile</button></div>`,"Tren, bukan vonis.")}${panel("Aktivitas terakhir",acts,"Lima aktivitas terbaru di sesi ini.")}</div><div class="stack"><section class="panel glass profile-card"><div class="avatar-large">${escapeHtml((state.profile.nickname||"G").slice(0,1).toUpperCase())}</div><h3>${escapeHtml(state.profile.nickname||"Pengunjung")}</h3><p><span class="guest-badge"><span class="status-dot"></span> Mode Pengunjung</span></p><div class="profile-meta"><div><small>Kelas</small><strong>${state.profile.grade||"XI"}</strong></div><div><small>Tahun ajaran</small><strong>${escapeHtml(state.profile.year||"—")}</strong></div><div><small>Mata pelajaran</small><strong>${state.profile.subjects.length}</strong></div><div><small>Plan B</small><strong>${state.alternatives.length} alternatif</strong></div></div><button class="btn secondary" style="width:100%;margin-top:15px" data-page="Academic Profile">Lengkapi profil</button></section>${panel("Progres keputusan",`<div class="progress-list"><div class="progress-row"><label>Profil akademik</label><strong>${pct}%</strong><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div></div><div class="progress-row"><label>Perbandingan program</label><strong>${Math.min(100,state.compared.length/2*100)}%</strong><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,state.compared.length/2*100)}%"></div></div></div><div class="progress-row"><label>Aspek keputusan</label><strong>${Math.round(checked/12*100)}%</strong><div class="progress-track"><div class="progress-fill" style="width:${checked/12*100}%"></div></div></div></div>`,"Progres membantu melihat langkah, bukan menilai dirimu.")}${panel("Pilihan saat ini",state.mainChoice?`<div class="quick-action"><span class="quick-icon">✦</span><span><strong>${escapeHtml(programById(state.mainChoice)?.name||"Pilihan utama")}</strong><small>Pilihan utama</small></span></div>`:`<div class="empty-state"><h3>Belum ada pilihan utama</h3><p>Pilih program yang ingin Anda pertimbangkan lebih lanjut.</p><button class="btn secondary small" data-page="Plan B Builder">Mulai Plan B</button></div>`)}</div></div>`;
}
function profilePage(){
 const rows=state.profile.subjects.map((s,i)=>`<tr><td>${escapeHtml(s.name)}</td><td>${escapeHtml(s.semester)}</td><td>${escapeHtml(s.year)}</td><td><strong>${s.grade}</strong></td><td><span class="data-tag ${s.source==="Data Contoh"?"sample":""}">${escapeHtml(s.source||"Input manual")}</span></td><td><div class="table-actions"><button class="text-btn" data-edit-subject="${i}">Edit</button><button class="text-btn" data-delete-subject="${i}">Hapus</button></div></td></tr>`).join("");
 return `${pageHead("Academic Profile","Catat nilai sebagai salah satu bahan pertimbangan, bukan penentu pilihan Anda.",`<button class="btn secondary small" id="importSample">Impor Data Contoh</button>`)}<div class="notice">Profil dan catatan eksplorasi tersimpan di perangkat ini; setelah login sebagai siswa, data profil dan catatan pilihan juga disinkronkan ke server JALUR. Nilai e-Rapor sekolah tetap berasal dari portal sekolah.</div><section class="panel glass"><div class="panel-head"><div><h2>Informasi dasar</h2><p class="panel-sub">Isi seperlunya. Nama panggilan bersifat opsional.</p></div><span class="data-tag sample">Input manual</span></div><form id="profileForm"><div class="form-grid"><div class="field"><label for="nickname">Nama panggilan (opsional)</label><input id="nickname" name="nickname" maxlength="40" value="${escapeHtml(state.profile.nickname)}" placeholder="Mis. Raka"></div><div class="field"><label for="grade">Kelas</label><select id="grade" name="grade"><option ${state.profile.grade==="XI"?"selected":""}>XI</option><option ${state.profile.grade==="X"?"selected":""}>X</option><option ${state.profile.grade==="XII"?"selected":""}>XII</option></select></div><div class="field"><label for="year">Tahun ajaran</label><input id="year" name="year" value="${escapeHtml(state.profile.year)}" placeholder="2026/2027" required></div></div><div class="form-actions"><button class="btn primary" type="submit">Simpan profil</button></div></form></section><section class="panel glass section-gap"><div class="panel-head"><div><h2>Nilai mata pelajaran</h2><p class="panel-sub">Nilai skala 0–100. Hindari memasukkan data pribadi yang tidak diperlukan.</p></div><button class="btn primary small" id="addSubject">＋ Tambah nilai</button></div>${rows?`<div class="table-wrap"><table class="data-table"><caption class="sr-only">Daftar nilai mata pelajaran</caption><thead><tr><th scope="col">Mata pelajaran</th><th scope="col">Semester</th><th scope="col">Tahun ajaran</th><th scope="col">Nilai</th><th scope="col">Sumber</th><th scope="col">Aksi</th></tr></thead><tbody>${rows}</tbody></table></div>`:`<div class="empty-state"><div class="empty-icon">▤</div><h3>Profilmu masih kosong</h3><p>Isi nilai untuk membantu membandingkan program, atau impor Data Contoh untuk mencoba.</p><button class="btn secondary small" id="addSubjectEmpty">Tambah nilai pertama</button></div>`}<p class="source-line">Kelengkapan: ${state.profile.subjects.length===0?"Kosong":state.profile.subjects.length<3?"Dasar":state.profile.subjects.length<6?"Cukup":"Lengkap"} · Cukup = minimal 6 mata pelajaran (batas tampilan).</p></section>`;
}
function programById(id){return programs.find(p=>p.id===id)}
function normalizeSearch(value=""){
 return String(value??"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLocaleLowerCase("id").replace(/[^\p{L}\p{N}]+/gu," ").replace(/\s+/g," ").trim();
}
function alpha(a,b){return String(a||"").localeCompare(String(b||""),"id",{sensitivity:"base",numeric:true});}
// Build search documents once from every row in the integrated database. Query tokens can
// appear in any order, and search never depends on the currently visible page of results.
const programSearchIndex=programs.map(p=>({...p,_search:normalizeSearch([p.name,p.campus,p.field,p.group,p.province,p.city,p.location,p.code,p.level,p.programAccreditation,p.institutionAccreditation].filter(Boolean).join(" "))})).sort((a,b)=>alpha(a.name,b.name)||alpha(a.campus,b.campus)||alpha(a.level,b.level));
const institutionSearchIndex=institutions.map(i=>({...i,_search:normalizeSearch([i.name,i.province,i.city,i.form,i.group,i.status,i.accreditation,i.address].filter(Boolean).join(" "))})).sort((a,b)=>alpha(a.name,b.name)||alpha(a.province,b.province));
const institutionProgramCounts=new Map();
for(const p of programs){const key=String(p.institutionId??"");if(key)institutionProgramCounts.set(key,(institutionProgramCounts.get(key)||0)+1);}
function matchesQuery(searchDocument,query){if(!query)return true;return searchDocument.includes(query);}
function explorerPage(){
 const q=window.explorerQuery||"",scope=window.explorerScope||"Semua hasil",field=window.explorerField||"Semua bidang",level=window.explorerLevel||"Semua jenjang",province=window.explorerProvince||"Semua provinsi";
 const query=normalizeSearch(q);
 const fields=[...new Set(programs.map(p=>p.field).filter(Boolean))].sort(alpha);
 const levels=[...new Set(programs.map(p=>p.level).filter(Boolean))].sort(alpha);
 const provinces=[...new Set([...programs.map(p=>p.province),...institutions.map(i=>i.province)].filter(Boolean))].sort(alpha);
 const matchedPrograms=programSearchIndex.filter(p=>
   matchesQuery(p._search,query)&&(field==="Semua bidang"||p.field===field)&&(level==="Semua jenjang"||p.level===level)&&(province==="Semua provinsi"||p.province===province)
 );
 const matchedInstitutions=institutionSearchIndex.filter(i=>
   matchesQuery(i._search,query)&&(province==="Semua provinsi"||i.province===province)
 );
 const mixed=[
  ...(scope!=="Perguruan tinggi"?matchedPrograms.map(p=>({kind:"program",name:p.name,secondary:p.campus,sortKey:p.name,item:p})):[]),
  ...(scope!=="Program studi"?matchedInstitutions.map(i=>({kind:"institution",name:i.name,secondary:[i.city,i.province].filter(Boolean).join(", "),sortKey:i.name,item:i})):[])
 ].sort((a,b)=>alpha(a.sortKey,b.sortKey)||alpha(a.kind,b.kind)||alpha(a.secondary,b.secondary));
 const limit=window.explorerLimit||30;
 const list=mixed.slice(0,limit);
 const dbCount=programSearchIndex.length,instCount=institutionSearchIndex.length;
 const formatNum=n=>Number(n).toLocaleString("id-ID");
 const resultCards=list.map(r=>{
  if(r.kind==="program"){
   const p=r.item;
   return `<article class="program-card glass search-result-card"><span class="program-kicker">PROGRAM STUDI · ${escapeHtml(p.level||"Jenjang tidak tercantum")}</span><h3>${escapeHtml(p.name||"Nama program studi tidak tercantum")}</h3><p class="campus">${escapeHtml(p.campus||"Perguruan tinggi tidak tercantum")}${p.city?` · ${escapeHtml(p.city)}`:""}${p.province?`, ${escapeHtml(p.province)}`:""}</p><div class="program-tags">${p.field?`<span class="tag">${escapeHtml(p.field)}</span>`:""}${p.programAccreditation?`<span class="tag">Akreditasi prodi: ${escapeHtml(p.programAccreditation)}</span>`:""}${p.status?`<span class="tag">${escapeHtml(p.status)}</span>`:""}</div><p class="source-line">Kode: ${escapeHtml(String(p.code||"Tidak tercantum"))} · Referensi: ${escapeHtml(String(p.updated||"Tidak tercantum"))} · ${escapeHtml(p.verification||"Status verifikasi tidak tercantum")}</p><div class="card-bottom"><button class="btn secondary" data-detail-program="${escapeHtml(p.id)}">Detail program</button><button class="btn ${state.mainChoice===p.id?"primary":"secondary"}" data-set-main="${escapeHtml(p.id)}">${state.mainChoice===p.id?"✓ Pilihan utama":"Jadikan utama"}</button><button class="btn ${state.compared.includes(p.id)?"primary":"secondary"}" data-compare="${escapeHtml(p.id)}">${state.compared.includes(p.id)?"✓ Dibandingkan":"⇄ Bandingkan"}</button></div></article>`;
  }
  const i=r.item,website=i.website&&/^https?:\/\//i.test(i.website)?i.website:"",pddikti=i.pddikti&&/^https?:\/\//i.test(i.pddikti)?i.pddikti:"";
  const count=institutionProgramCounts.get(String(i.id))||0;
  return `<article class="program-card glass search-result-card"><span class="program-kicker">PERGURUAN TINGGI${i.form?` · ${escapeHtml(i.form)}`:""}</span><h3>${escapeHtml(i.name||"Nama perguruan tinggi tidak tercantum")}</h3><p class="campus">${escapeHtml([i.city,i.province].filter(Boolean).join(", ")||"Lokasi tidak tercantum")}</p><div class="program-tags">${i.group?`<span class="tag">${escapeHtml(i.group)}</span>`:""}${i.status?`<span class="tag">${escapeHtml(i.status)}</span>`:""}${i.accreditation?`<span class="tag">Akreditasi institusi: ${escapeHtml(i.accreditation)}</span>`:""}</div><p class="source-line">${formatNum(count)} program studi terhubung dalam basis data · Referensi: ${escapeHtml(String(i.year||"Tidak tercantum"))} · ${escapeHtml(i.verification||"Status verifikasi tidak tercantum")}</p><div class="card-bottom">${website?`<a class="btn secondary" href="${escapeHtml(website)}" target="_blank" rel="noopener noreferrer">Situs resmi ↗</a>`:""}${pddikti?`<a class="btn secondary" href="${escapeHtml(pddikti)}" target="_blank" rel="noopener noreferrer">PDDikti ↗</a>`:`<a class="btn secondary" href="https://pddikti.kemdiktisaintek.go.id/" target="_blank" rel="noopener noreferrer">Cari di PDDikti ↗</a>`}<button class="btn secondary" data-search-campus="${escapeHtml(i.name||"")}">Lihat program studi</button></div></article>`;
 }).join("");
 return `${pageHead("Penjelajah Program Studi","Satu pencarian terpadu untuk nama perguruan tinggi maupun nama program studi. Semua entri dalam basis data lokal dapat dicari; hasil diurutkan alfabetis.")}<div class="notice"><strong>Direktori basis data lengkap.</strong> Memuat ${formatNum(dbCount)} entri program studi dan ${formatNum(instCount)} entri perguruan tinggi. Pencarian mencakup seluruh entri tersebut, bukan hanya hasil yang sedang terlihat. Hasil ditampilkan bertahap agar halaman tetap responsif.</div>
 <section class="panel glass search-directory"><div class="panel-head"><div><h2>Temukan pilihan pendidikan tinggi</h2><p class="panel-sub">Ketik nama universitas/perguruan tinggi, jurusan, program studi, kota, kode, atau bidang.</p></div><span class="data-tag">${formatNum(dbCount+instCount)} entri</span></div>
 <div class="search-row directory-search-row"><input class="search-input" id="programSearch" type="search" value="${escapeHtml(q)}" placeholder="Contoh: Universitas Indonesia, Kedokteran, Teknik Informatika…" aria-label="Cari universitas atau program studi"><select class="filter-select" id="searchScope" aria-label="Jenis hasil pencarian"><option ${scope==="Semua hasil"?"selected":""}>Semua hasil</option><option ${scope==="Program studi"?"selected":""}>Program studi</option><option ${scope==="Perguruan tinggi"?"selected":""}>Perguruan tinggi</option></select></div>
 <div class="search-row search-filters"><select class="filter-select" id="fieldFilter" aria-label="Filter bidang"><option>Semua bidang</option>${fields.map(f=>`<option ${f===field?"selected":""}>${escapeHtml(f)}</option>`).join("")}</select><select class="filter-select" id="levelFilter" aria-label="Filter jenjang"><option>Semua jenjang</option>${levels.map(l=>`<option ${l===level?"selected":""}>${escapeHtml(l)}</option>`).join("")}</select><select class="filter-select" id="provinceFilter" aria-label="Filter provinsi"><option>Semua provinsi</option>${provinces.map(v=>`<option ${v===province?"selected":""}>${escapeHtml(v)}</option>`).join("")}</select><button class="btn secondary small" id="resetExplorer">Reset</button></div>
 <div class="directory-summary"><strong>${formatNum(mixed.length)} hasil ditemukan</strong><span>Urutan alfabetis A–Z</span><span>Menampilkan ${formatNum(Math.min(limit,mixed.length))} dari ${formatNum(mixed.length)}</span></div>
 <div class="program-grid" id="directoryResults">${resultCards||`<div class="empty-state" style="grid-column:1/-1"><div class="empty-icon">⌕</div><h3>${query?"Tidak ada hasil yang cocok":"Mulai pencarian"}</h3><p>${query?"Coba kata kunci lain, periksa ejaan, atau reset filter.":"Ketik nama universitas, jurusan, atau program studi. Hasil akan dicari pada seluruh basis data."}</p><button class="btn secondary small" id="resetExplorerEmpty">Reset pencarian</button></div>`}</div>
 ${mixed.length>list.length?`<div class="center-actions section-gap"><button class="btn secondary" id="loadMorePrograms">Tampilkan ${formatNum(Math.min(30,mixed.length-list.length))} hasil berikutnya</button></div>`:""}
 <p class="source-line">Entri kosong pada sumber asli tetap ditandai “tidak tercantum”, bukan diisi dengan perkiraan. Data akreditasi, lokasi, dan status mengikuti berkas basis data terlampir dan perlu diverifikasi ke sumber resmi.</p></section>
 <section class="panel glass section-gap"><div class="panel-head"><div><h2>Ringkasan cakupan data</h2><p class="panel-sub">Jumlah entri yang dimuat pada aplikasi ini.</p></div></div><div class="stat-grid">${statCard("⌕","Program studi",formatNum(dbCount),"Seluruh entri tersedia melalui pencarian","Study Program Explorer")}${statCard("⌂","Perguruan tinggi",formatNum(instCount),"Seluruh entri tersedia melalui pencarian","Study Program Explorer")}${statCard("A–Z","Pengurutan","Alfabetis","Nama program dan perguruan tinggi","Study Program Explorer")}</div></section>
 <section class="panel glass section-gap"><div class="panel-head"><div><h2>Statistik seleksi nasional</h2><p class="panel-sub">Angka agregat nasional yang tersedia pada dataset; bukan peluang pribadi atau angka per program studi.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Tahun</th><th>Jalur</th><th>Daya tampung</th><th>Pendaftar</th><th>Diterima</th><th>Diterima/pendaftar</th><th>Sumber</th></tr></thead><tbody>${(window.JALUR_DB?.nationalStats||[]).map(s=>`<tr><td>${escapeHtml(String(s.year??"—"))}</td><td>${escapeHtml(String(s.route??"—"))}</td><td>${s.capacity_total==null?"Tidak tersedia":formatNum(s.capacity_total)}</td><td>${s.applicants_total==null?"Tidak tersedia":formatNum(s.applicants_total)}</td><td>${s.admitted_total==null?"Tidak tersedia":formatNum(s.admitted_total)}</td><td>${s.admitted_to_applicants_pct==null?"Tidak tersedia":`${escapeHtml(String(s.admitted_to_applicants_pct))}%`}</td><td>${s.source_url?`<a href="${escapeHtml(s.source_url)}" target="_blank" rel="noopener noreferrer">Sumber ↗</a>`:"Tidak tersedia"}</td></tr>`).join("")}</tbody></table></div><p class="source-line">Angka agregat tidak dapat digunakan sebagai skor ambang atau peluang kelulusan individual.</p></section>`;
}
function alumniPage(){
 const prompts=[['Kegiatan belajar','Seperti apa satu minggu perkuliahan yang umum? Berapa banyak kuliah, proyek, diskusi, praktikum, atau tugas mandiri?'],['Tugas dan tantangan','Tugas apa yang paling sering ditemui? Kemampuan apa yang ternyata paling dibutuhkan?'],['Dukungan kampus','Bagaimana akses ke dosen, penasihat akademik, layanan konseling, beasiswa, dan fasilitas belajar?'],['Kehidupan sehari-hari','Bagaimana transportasi, tempat tinggal, organisasi, biaya hidup, dan keseimbangan waktu?'],['Refleksi pilihan','Apa yang ingin diketahui sebelum masuk? Apa yang akan disarankan untuk calon mahasiswa?']];
 return `${pageHead("Pengalaman Alumni","Gunakan panduan ini untuk mengumpulkan pengalaman nyata dari mahasiswa atau alumni. JALUR tidak mengarang testimoni orang dan belum menyertakan kumpulan wawancara alumni terverifikasi.")}
 <div class="notice"><strong>Transparansi sumber.</strong> Belum ada testimoni alumni terverifikasi yang disertakan dalam basis data. Bagian ini menyediakan panduan wawancara agar informasi yang Anda kumpulkan berasal dari pengalaman nyata dan dapat diberi konteks.</div>
 <section class="panel glass"><div class="panel-head"><div><h2>Pertanyaan untuk mahasiswa atau alumni</h2><p class="panel-sub">Pilih pertanyaan yang relevan dengan program dan kampus yang sedang dipertimbangkan.</p></div><span class="data-tag">Panduan praktis</span></div><div class="program-grid">${prompts.map((x,i)=>`<article class="program-card glass"><span class="program-kicker">PERTANYAAN ${String(i+1).padStart(2,"0")}</span><h3>${escapeHtml(x[0])}</h3><p>${escapeHtml(x[1])}</p><button class="btn secondary" data-copy-question="${i}">Salin pertanyaan</button></article>`).join("")}</div></section>
 <section class="panel glass section-gap"><h2>Catat wawancara atau temuan</h2><p class="panel-sub">Jangan mencatat data pribadi narasumber tanpa izin. Pisahkan pengalaman pribadi dari fakta yang perlu diverifikasi.</p><form id="alumniNoteForm" class="form-grid"><div class="field"><label for="alumniProgram">Program studi / kampus</label><input id="alumniProgram" placeholder="Nama program studi dan perguruan tinggi" maxlength="180"></div><div class="field"><label for="alumniSource">Sumber pengalaman</label><select id="alumniSource"><option>Mahasiswa aktif</option><option>Alumni</option><option>Guru BK / konselor</option><option>Sumber publik</option></select></div><div class="field full"><span class="field-label">Hal yang dikonfirmasi dari narasumber (pilih yang relevan)</span>${choiceChecklist("alumniFindings",["Kegiatan kuliah dan praktikum","Beban tugas dan penilaian","Pengalaman dosen dan dukungan akademik","Biaya hidup dan tempat tinggal","Organisasi dan kehidupan kampus","Magang dan pengalaman kerja","Saran untuk calon mahasiswa","Informasi masih perlu diverifikasi"],[])}</div><div class="field full"><button class="btn primary" type="submit">Simpan ke Jurnal Keputusan</button></div></form></section>
 <section class="panel glass section-gap"><h2>Tempat memverifikasi informasi program</h2><div class="form-actions"><a class="btn secondary" href="https://pddikti.kemdiktisaintek.go.id/" target="_blank" rel="noopener noreferrer">PDDikti ↗</a><a class="btn secondary" href="https://snpmb.id/" target="_blank" rel="noopener noreferrer">SNPMB ↗</a><button class="btn secondary" data-page="Study Program Explorer">Cari program di JALUR</button></div></section>`;
}
function choiceChecklist(group, options, selected=[]){return `<div class="choice-check-grid" role="group" aria-label="Pilihan terstruktur">${options.map(option=>`<label class="choice-check"><input type="checkbox" data-choice-group="${escapeHtml(group)}" value="${escapeHtml(option)}" ${selected.includes(option)?"checked":""}><span>${escapeHtml(option)}</span></label>`).join("")}</div>`;}
function readChoices(group){return $("[data-choice-group]:checked").filter(el=>el.dataset.choiceGroup===group).map(el=>el.value);}
function comparisonPage(){
 const selected=state.compared.map(programById).filter(Boolean);
 return `${pageHead("Decision Comparison","Bandingkan informasi yang tersedia dan tambahkan kriteria pribadi. Tidak ada skor atau peringkat otomatis.",`<button class="btn secondary small" id="clearComparison">Kosongkan</button>`)}<div class="notice">Maksimal 4 program. Data berasal dari basis data JALUR; periksa tahun referensi dan sumber resmi sebelum mengambil keputusan.</div><section class="panel glass"><div class="panel-head"><div><h2>Program studi yang dibandingkan</h2><p class="panel-sub">${selected.length} dari 4 program dipilih · minimal 2 untuk mulai membandingkan</p></div><button class="btn secondary small" id="addCompare">＋ Tambah program</button></div><div class="compare-slots">${[0,1,2,3].map(i=>{const p=selected[i];return `<div class="compare-slot">${p?`<span class="program-kicker">${p.level} · ${p.field}</span><strong>${p.name}</strong><small>${p.campus}</small><button class="text-btn" data-remove-compare="${p.id}">Hapus pilihan</button>`:`<span class="quick-icon">＋</span><strong>Slot ${i+1}</strong><small>Belum ada program</small>`}</div>`}).join("")}</div></section>${selected.length>=2?`<section class="panel glass section-gap"><div class="panel-head"><div><h2>Tabel perbandingan</h2><p class="panel-sub">Kolom dapat digulir di ponsel.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th scope="col">Kriteria</th>${selected.map(p=>`<th scope="col">${p.name}</th>`).join("")}</tr></thead><tbody>${[["Perguruan tinggi",p=>p.campus],["Jenjang / bidang",p=>p.level+" · "+p.field],["Mata pelajaran relevan",p=>p.subjects.join(", ")],["Persyaratan",p=>p.requirements],["Sumber / pembaruan",p=>p.source+" · "+p.updated]].map(row=>`<tr><th scope="row">${row[0]}</th>${selected.map(p=>`<td>${row[1](p)}</td>`).join("")}</tr>`).join("")}</tbody></table></div><p class="source-line">Persamaan dan perbedaan di atas diturunkan dari data contoh yang tersedia. Tidak ada label “terbaik”.</p></section><section class="panel glass section-gap"><div class="panel-head"><div><h2>Catatan pribadi</h2><p class="panel-sub">Tulis hal yang penting untukmu pada tiap pilihan.</p></div></div><div class="comparison-cards">${selected.map(p=>`<div class="compare-program"><h3>${p.name}</h3><p class="panel-sub">Pilih pertimbangan yang sesuai untuk program ini.</p>${choiceChecklist("comparison:"+p.id,["Sesuai minat dan potensi","Kurikulum menarik","Biaya perlu diperiksa","Lokasi dan akses sesuai","Fasilitas dan dukungan penting","Prospek karier ingin ditelusuri"],state.notes.comparisonChoices?.[p.id]||[])}</div>`).join("")}</div><div class="form-actions"><button class="btn primary" id="saveNotes">Simpan catatan</button><button class="btn secondary" id="makePlan">Lanjut ke Plan B</button></div></section>`:`<section class="panel glass section-gap"><div class="empty-state"><div class="empty-icon">⇄</div><h3>Tambahkan minimal dua program</h3><p>Pilih program dari Explorer untuk mulai melihat persamaan dan perbedaannya.</p><button class="btn primary" data-page="Study Program Explorer">Jelajahi program studi</button></div></section>`}`;
}
function planBPage(){
 const main=programById(state.mainChoice);const alts=state.alternatives.map(programById).filter(Boolean);
 return `${pageHead("Plan B Builder","Susun pilihan utama dan alternatif beserta alasanmu. Plan B bukan jaminan peluang diterima.")}<div class="notice">Keputusan tetap milikmu. Pastikan informasi jalur dan persyaratan diverifikasi melalui sumber resmi.</div><section class="panel glass"><div class="panel-head"><div><h2>Pilihan utama</h2><p class="panel-sub">Pilih satu program dan tulis alasanmu.</p></div><span class="data-tag ${main?"sample":"pending"}">${main?"Terpilih":"Belum dipilih"}</span></div>${main?`<div class="quick-action"><span class="quick-icon">✦</span><span><strong>${main.name}</strong><small>${main.campus}</small></span><button class="text-btn" id="clearMain">Ubah</button></div>`:""}<form id="mainChoiceForm" class="section-gap"><div class="form-grid"><div class="field full"><label for="mainProgram">Program pilihan utama</label><input type="hidden" id="mainProgram" value="${escapeHtml(state.mainChoice||"")}" required><div class="picker-selection"><span id="mainProgramLabel">${state.mainChoice?escapeHtml(`${programById(state.mainChoice)?.name||"Program tidak ditemukan"} — ${programById(state.mainChoice)?.campus||""}`):"Belum ada program dipilih"}</span><button class="btn secondary" type="button" id="pickMainProgram">Cari program di direktori</button></div><small>Gunakan pencarian direktori untuk memilih dari seluruh basis data, bukan daftar terbatas.</small></div><div class="field full"><span class="field-label">Alasan memilih (pilih minimal satu)</span>${choiceChecklist("mainReasons",["Sesuai minat dan ketertarikan","Selaras dengan kekuatan akademik","Kurikulum dan mata kuliah menarik","Mendukung rencana karier","Biaya dan lokasi realistis","Memiliki fasilitas dan dukungan yang dibutuhkan"],state.notes.mainReasonChoices||[])}</div><div class="field full"><label for="mainCriteria">Kriteria utama</label><select id="mainCriteria"><option value="">Pilih kriteria utama</option>${["Minat dan ketertarikan","Kesesuaian akademik","Kurikulum","Prospek karier","Biaya pendidikan","Lokasi dan akses","Fasilitas kampus"].map(x=>`<option ${state.notes.mainCriteria===x?"selected":""}>${x}</option>`).join("")}</select></div></div><div class="form-actions"><button class="btn primary" type="submit">Simpan pilihan utama</button></div></form></section><section class="panel glass section-gap"><div class="panel-head"><div><h2>Alternatif pilihan</h2><p class="panel-sub">${alts.length} dari 3 alternatif</p></div><button class="btn secondary small" id="addAlternative" ${alts.length>=3?"disabled":""}>＋ Tambah alternatif</button></div>${alts.length?`<div class="quick-list">${alts.map((p,i)=>`<div class="quick-action"><span class="quick-icon">${i+1}</span><span><strong>${p.name}</strong><small>${p.campus}</small></span><button class="text-btn" data-remove-alt="${p.id}">Hapus</button></div>`).join("")}</div>`:`<div class="empty-state"><h3>Belum ada alternatif</h3><p>Alternatif membantu Anda menyiapkan pilihan lain yang tetap Anda pertimbangkan.</p></div>`}<p class="source-line">Setiap pilihan alternatif sebaiknya punya alasan dan hal yang perlu diverifikasi. Tambahkan catatan di Comparison.</p></section>`;
}
function blindSpotPage(){const count=state.checked.length;return `${pageHead("Decision Blind Spot Detector","Daftar ini membantu memeriksa hal-hal yang mungkin terlewat. Ini bukan penilaian terhadap dirimu.")}<section class="panel glass"><div class="panel-head"><div><h2>Progres tinjauan</h2><p class="panel-sub">${count} dari ${blindSpots.length} aspek sudah Anda tinjau.</p></div><strong>${Math.round(count/blindSpots.length*100)}%</strong></div><div class="progress-track" style="height:9px;margin-bottom:19px"><div class="progress-fill" style="width:${count/blindSpots.length*100}%"></div></div>${count===blindSpots.length?`<div class="notice">Semua aspek sudah Anda tinjau. Lanjut ke Decision Summary?</div>`:""}<div class="checklist">${blindSpots.map((b,i)=>{const done=state.checked.includes(i);return `<div class="check-item ${done?"done":""}"><input type="checkbox" id="spot-${i}" data-check-spot="${i}" ${done?"checked":""}><div><label for="spot-${i}"><strong>${b[0]}</strong></label><p>${b[1]}</p><button class="text-btn" data-page="${b[2]}">Lengkapi di ${b[2]} ↗</button></div><span class="check-status">${done?"✓ Sudah diperiksa":"○ Belum diperiksa"}</span></div>`}).join("")}</div><div class="form-actions"><button class="btn primary" data-page="Decision Summary">Buka Decision Summary</button></div></section>`}
function summaryPage(){const main=programById(state.mainChoice);const alts=state.alternatives.map(programById).filter(Boolean);const selected=state.compared.map(programById).filter(Boolean);return `${pageHead("Decision Summary","Ringkasan untuk dibawa ke diskusi dengan guru BK atau orang tua.",`<button class="btn secondary small" id="printSummary">Unduh / cetak PDF</button>`)}<div class="notice">Ringkasan disusun dari data pilihan dan masukan yang tercatat. Periksa status dan tanggal verifikasi setiap informasi melalui sumber resmi sebelum mengambil keputusan. Tidak ada prediksi kelulusan.</div><div class="summary-block glass"><span class="eyebrow">JALUR · RINGKASAN KEPUTUSAN</span><h2 style="margin-top:10px">Perjalanan pilihan pendidikan tinggi</h2><p>Dibuat pada ${new Date().toLocaleDateString("id-ID",{dateStyle:"long"})} · Mode: Pengunjung${state.profile.subjects.length?" dengan profil akademik":" · Profil belum diisi"}</p></div><div class="summary-block glass"><h3>1. Pilihan utama</h3>${main?`<p><strong>${main.name}</strong> — ${main.campus}</p><p><strong>Alasan:</strong> ${escapeHtml(state.notes.mainReason||"Alasan belum ditulis.")}</p><p><strong>Kriteria utama:</strong> ${escapeHtml(state.notes.mainCriteria||"Belum ditentukan.")}</p>`:`<p>Belum ada pilihan utama. <button class="text-btn" data-page="Plan B Builder">Lengkapi di Plan B Builder ↗</button></p>`}</div><div class="summary-block glass"><h3>2. Pilihan alternatif</h3>${alts.length?`<ul>${alts.map(p=>`<li>${p.name} — ${p.campus}</li>`).join("")}</ul>`:`<p>Belum ada alternatif yang dipilih. <button class="text-btn" data-page="Plan B Builder">Susun alternatif ↗</button></p>`}</div><div class="summary-block glass"><h3>3. Program dalam perbandingan</h3>${selected.length?`<ul>${selected.map(p=>`<li><strong>${p.name}</strong> — ${p.campus}${state.notes[p.id]?`<br>Catatan: ${escapeHtml(state.notes[p.id])}`:""}</li>`).join("")}</ul>`:`<p>Belum ada program dibandingkan. <button class="text-btn" data-page="Study Program Explorer">Jelajahi program ↗</button></p>`}</div><div class="summary-block glass"><h3>4. Aspek yang belum ditinjau</h3>${blindSpots.map((b,i)=>({b,i})).filter(x=>!state.checked.includes(x.i)).length?`<ul>${blindSpots.map((b,i)=>({b,i})).filter(x=>!state.checked.includes(x.i)).map(x=>`<li>${x.b[0]}</li>`).join("")}</ul>`:`<p>Semua aspek sudah ditandai telah ditinjau.</p>`}<button class="btn secondary small" data-page="Decision Blind Spot Detector">Tinjau aspek</button></div><div class="summary-block glass"><h3>5. Pertanyaan untuk diskusi</h3><ul><li>Informasi apa yang perlu saya verifikasi sebelum menetapkan pilihan?</li><li>Alternatif apa yang realistis dengan mempertimbangkan minat, lokasi, dan biaya?</li><li>Dukungan atau sumber informasi apa yang sebaiknya saya cari berikutnya?</li></ul></div><section class="summary-block glass"><h3>6. Verifikasi sebelum keputusan</h3><ul><li><strong>Belum diverifikasi otomatis:</strong> kurikulum, biaya, daya tampung, dan jadwal seleksi.</li><li>Catat tanggal terakhir memeriksa informasi dan simpan tautan sumber resmi.</li><li>Utamakan PDDikti, laman penerimaan resmi kampus, dan portal SNPMB.</li></ul></section><p class="source-line">Sumber data: input pengguna dan basis data direktori JALUR. Informasi penerimaan, biaya, dan kurikulum harus diperiksa melalui sumber resmi.</p>`}
function settingsPage(){return `${pageHead("Settings","Atur keterbacaan serta kelola data yang tersimpan pada peramban ini.")}<section class="panel glass"><div class="panel-head"><div><h2>Tampilan dan aksesibilitas</h2><p class="panel-sub">Pengaturan berlaku pada peramban yang sedang digunakan.</p></div></div><div class="settings-row"><div><strong>Perbesar teks</strong><p>Meningkatkan ukuran teks agar lebih mudah dibaca.</p></div><input type="checkbox" id="largeText" ${state.settings.largeText?"checked":""} aria-label="Perbesar teks"></div><div class="settings-row"><div><strong>Kurangi animasi</strong><p>Mengurangi gerakan dan transisi dekoratif.</p></div><input type="checkbox" id="reduceMotion" ${state.settings.reduceMotion?"checked":""} aria-label="Kurangi animasi"></div></section><section class="panel glass section-gap"><div class="panel-head"><div><h2>Pencadangan dan privasi</h2><p class="panel-sub">Data tersimpan secara lokal di peramban ini. Cadangan dapat dipindahkan secara manual.</p></div></div><div class="settings-row"><div><strong>Unduh cadangan data</strong><p>Menyimpan profil, nilai, catatan, pilihan, dan progres dalam berkas JSON.</p></div><button class="btn secondary small" id="exportData">Unduh cadangan</button></div><div class="settings-row"><div><strong>Pulihkan cadangan</strong><p>Memuat cadangan JALUR yang sebelumnya diunduh. Data saat ini akan digantikan.</p></div><div><input type="file" id="importDataFile" accept="application/json,.json" hidden><button class="btn secondary small" id="importData">Pilih berkas</button></div></div><div class="settings-row"><div><strong>Hapus seluruh data aplikasi</strong><p>Menghapus profil, nilai, catatan, perbandingan, dan progres dari peramban ini.</p></div><button class="btn secondary small" id="resetSession">Hapus data</button></div><p class="source-line">Jangan membagikan berkas cadangan jika berisi informasi yang ingin Anda jaga kerahasiaannya.</p></section>`}
function helpPage(){return `${pageHead("Help / About","Informasi mengenai tujuan, batasan, dan cara kerja JALUR.")}<section class="panel glass"><h2>Apa itu JALUR?</h2><p>JALUR adalah website pendamping pengambilan keputusan pendidikan tinggi. Aplikasi ini membantu siswa menyusun informasi, menimbang beberapa program studi, dan menyiapkan pertanyaan untuk didiskusikan bersama orang tua/wali atau guru bimbingan dan konseling.</p><h3>Fitur yang tersedia</h3><ol><li><strong>Profil Akademik:</strong> mencatat nilai mata pelajaran secara manual.</li><li><strong>Penjelajah Program Studi:</strong> menelusuri data ilustrasi dan mencari metadata institusi melalui layanan daring.</li><li><strong>Pengalaman Alumni:</strong> membaca ilustrasi pengalaman untuk bahan refleksi; seluruh cerita merupakan simulasi.</li><li><strong>Perbandingan Program Studi:</strong> membandingkan beberapa pilihan dan menyimpan catatan pribadi.</li><li><strong>Rencana Alternatif:</strong> menyusun pilihan utama dan alternatif.</li><li><strong>Daftar Periksa Keputusan:</strong> meninjau aspek yang perlu diperiksa sebelum mengambil keputusan.</li><li><strong>Ringkasan Keputusan:</strong> menyiapkan rangkuman untuk dicetak atau dibahas bersama pihak tepercaya.</li><li><strong>Pusat Informasi Resmi:</strong> membuka tautan lembaga dan layanan terkait pendidikan tinggi.</li></ol><h3>Ketepatan informasi</h3><p>Daftar program studi dan cerita alumni bawaan adalah data contoh, bukan basis data resmi terkini. Pencarian institusi daring menggunakan metadata OpenAlex dan tidak memuat ketentuan penerimaan, biaya, atau akreditasi yang dapat dijadikan acuan final. Selalu konfirmasikan informasi melalui situs resmi.</p><h3>Privasi dan penyimpanan</h3><p>Data profil dan catatan disimpan di penyimpanan lokal peramban apabila tersedia. Data tidak otomatis disinkronkan antarlaptop atau ponsel. Anda dapat mengunduh cadangan atau menghapus data melalui Pengaturan.</p><h3>Batasan penggunaan</h3><p>JALUR bukan sistem penerimaan mahasiswa baru, bukan alat prediksi kelulusan, dan tidak menetapkan program studi terbaik. Gunakan aplikasi sebagai alat bantu berpikir, bukan sebagai satu-satunya dasar keputusan.</p><div class="form-actions"><button class="btn primary" data-page="User Guide">Baca panduan penggunaan</button><button class="btn secondary" data-page="Official Sources">Buka pusat informasi resmi</button></div></section>`}
function guidePage(){return `${pageHead("User Guide","Ikuti urutan berikut untuk menggunakan JALUR secara bertahap. Anda tidak harus mengisi semua bagian sekaligus.")}<section class="panel glass"><h2>Alur penggunaan yang disarankan</h2><ol class="guide-steps"><li><strong>Mulai dari Profil Akademik.</strong><p>Masukkan kelas, tahun ajaran, dan nilai mata pelajaran yang ingin Anda jadikan bahan pertimbangan. Gunakan nilai yang benar; data contoh hanya untuk mencoba fitur.</p></li><li><strong>Jelajahi program studi.</strong><p>Gunakan kolom pencarian dan filter bidang untuk menyaring daftar contoh. Buka detail program untuk membaca ringkasannya.</p></li><li><strong>Verifikasi informasi di sumber resmi.</strong><p>Buka Pusat Informasi Resmi untuk memeriksa jalur seleksi, jadwal, biaya, beasiswa, dan persyaratan. Catat tanggal saat Anda memeriksa informasi.</p></li><li><strong>Bandingkan dua hingga empat program.</strong><p>Pada halaman Penjelajah Program Studi, tekan tombol Bandingkan. Buka Perbandingan Program Studi, lalu isi catatan mengenai minat, lokasi, biaya, kurikulum, dan dukungan yang tersedia.</p></li><li><strong>Tetapkan pilihan utama dan alternatif.</strong><p>Gunakan Rencana Alternatif untuk menulis alasan pilihan utama dan menambahkan hingga tiga alternatif. Alternatif bukan jaminan penerimaan.</p></li><li><strong>Tinjau daftar periksa.</strong><p>Periksa setiap aspek yang relevan, termasuk persyaratan, biaya, tempat tinggal, jadwal seleksi, dan rencana jika hasilnya tidak sesuai harapan.</p></li><li><strong>Buat ringkasan keputusan.</strong><p>Buka Ringkasan Keputusan untuk meninjau hasil pertimbangan. Anda dapat mencetaknya dan membawanya saat berdiskusi dengan orang tua/wali atau guru bimbingan dan konseling.</p></li></ol></section><section class="panel glass section-gap"><h2>Memahami label data</h2><ul><li><strong>Input manual:</strong> informasi yang Anda masukkan sendiri.</li><li><strong>Data Contoh:</strong> data ilustrasi yang disertakan untuk mencoba antarmuka; bukan informasi resmi terkini.</li><li><strong>Data Simulasi:</strong> cerita atau contoh rekaan untuk membantu memahami fitur; bukan pengalaman orang nyata.</li><li><strong>Data daring:</strong> informasi yang diminta dari layanan pihak ketiga. Periksa nama sumber dan tanggal aksesnya.</li></ul><div class="notice">JALUR tidak memperkirakan peluang kelulusan dan tidak menentukan pilihan terbaik secara otomatis. Keputusan sebaiknya dibuat dengan mempertimbangkan minat, kemampuan, kondisi keluarga, dan informasi resmi yang terbaru.</div><h2>Privasi dan penyimpanan</h2><p>Data tersimpan di penyimpanan lokal peramban pada perangkat yang digunakan. Data tidak otomatis tersinkronisasi ke perangkat lain. Jangan memasukkan kata sandi, nomor identitas, atau informasi pribadi yang tidak diperlukan. Gunakan Pengaturan untuk menghapus data aplikasi pada peramban ini.</p><div class="form-actions"><button class="btn primary" data-page="Academic Profile">Mulai dari Profil Akademik</button><button class="btn secondary" data-page="Official Sources">Buka Pusat Informasi Resmi</button></div></section>`}
function sourcesPage(){const links=[['SNPMB','Seleksi Nasional Penerimaan Mahasiswa Baru','https://snpmb.id/','Informasi resmi SNBP, SNBT, dan pengumuman terkait seleksi nasional.'],['PDDikti','Pangkalan Data Pendidikan Tinggi','https://pddikti.kemdiktisaintek.go.id/','Untuk menelusuri informasi perguruan tinggi dan program studi yang tercatat.'],['BAN-PT','Badan Akreditasi Nasional Perguruan Tinggi','https://www.banpt.or.id/','Untuk memeriksa informasi akreditasi melalui layanan resminya.'],['KIP Kuliah','Program Kartu Indonesia Pintar Kuliah','https://kip-kuliah.kemdiktisaintek.go.id/','Untuk memeriksa ketentuan bantuan biaya pendidikan dan informasi pendaftaran.'],['Kemdiktisaintek','Kementerian Pendidikan Tinggi, Sains, dan Teknologi','https://kemdiktisaintek.go.id/','Kebijakan dan pengumuman dari kementerian.']];return `${pageHead("Official Sources","Gunakan sumber resmi untuk memeriksa informasi yang dapat berubah dari tahun ke tahun.")}<div class="notice">Tautan di bawah membuka situs eksternal. JALUR tidak mengendalikan isi atau ketersediaan situs tersebut. Periksa tanggal, tahun seleksi, dan ketentuan yang berlaku.</div><div class="program-grid source-directory">${links.map(l=>`<article class="program-card glass"><span class="program-kicker">SUMBER EKSTERNAL</span><h3>${l[0]}</h3><p class="campus">${l[1]}</p><p>${l[3]}</p><div class="card-bottom"><a class="btn primary" href="${l[2]}" target="_blank" rel="noopener noreferrer">Buka situs resmi ↗</a></div></article>`).join('')}</div><section class="panel glass section-gap"><h2>Catatan pemeriksaan informasi</h2><p>Untuk setiap program yang Anda pertimbangkan, catat nama perguruan tinggi, nama program studi, jalur masuk, tahun seleksi, persyaratan, biaya pendidikan, tenggat pendaftaran, tautan sumber, dan tanggal pemeriksaan. Informasi dari forum, media sosial, atau hasil mesin pencari sebaiknya dikonfirmasi kembali pada situs resmi.</p><div class="form-actions"><button class="btn secondary" data-page="Study Program Explorer">Kembali ke Penjelajah Program Studi</button></div></section>`}

async function searchInstitutions(){
 const input=$("#institutionQuery"),target=$("#institutionResults");if(!input||!target)return;
 const query=input.value.trim().toLocaleLowerCase("id");
 if(query.length<2){toast("Masukkan sekurang-kurangnya dua karakter.","error");return}
 target.innerHTML='<p class="source-line">Sedang mencari direktori institusi…</p>';
 const results=institutions.filter(i=>[i.name,i.province,i.city,i.form,i.group,i.accreditation].filter(Boolean).join(" ").toLocaleLowerCase("id").includes(query)).slice(0,12);
 if(!results.length){target.innerHTML='<div class="empty-state"><h3>Institusi tidak ditemukan</h3><p>Coba kata kunci lain. Direktori ini mengikuti isi berkas basis data yang disertakan dan mungkin belum mencakup pembaruan terbaru.</p><a class="btn secondary" href="https://pddikti.kemdiktisaintek.go.id/" target="_blank" rel="noopener noreferrer">Cari melalui PDDikti ↗</a></div>';return}
 target.innerHTML=`<p class="source-line">Menampilkan ${results.length} hasil teratas. Hasil ini berasal dari berkas lokal yang disertakan.</p><div class="program-grid">${results.map(i=>`<article class="program-card glass"><span class="program-kicker">${escapeHtml(i.form||"Perguruan tinggi")}${i.group?` · ${escapeHtml(i.group)}`:""}</span><h3>${escapeHtml(i.name||"Nama tidak tersedia")}</h3><p class="campus">${escapeHtml([i.city,i.province].filter(Boolean).join(", ")||"Lokasi tidak tercantum")}</p><div class="program-tags">${i.accreditation?`<span class="tag">Akreditasi: ${escapeHtml(i.accreditation)}</span>`:""}${i.status?`<span class="tag">${escapeHtml(i.status)}</span>`:""}</div><p class="source-line">Tahun referensi: ${escapeHtml(String(i.year||"Tidak tercantum"))}${i.verification?` · Verifikasi: ${escapeHtml(i.verification)}`:""}</p><div class="card-bottom">${i.website?`<a class="btn secondary" href="${escapeHtml(i.website)}" target="_blank" rel="noopener noreferrer">Situs resmi ↗</a>`:""}${i.pddikti?`<a class="btn secondary" href="${escapeHtml(i.pddikti)}" target="_blank" rel="noopener noreferrer">PDDikti ↗</a>`:""}</div></article>`).join("")}</div><p class="source-line">Akreditasi dan status dapat berubah. Gunakan tautan sumber dan lakukan verifikasi sebelum mengambil keputusan.</p>`;
}
function openModal(title,body,footer=""){ $("#modalRoot").innerHTML=`<div class="modal-backdrop" id="modalBackdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-head"><h2 id="modalTitle">${title}</h2><button class="modal-close" id="modalClose" aria-label="Tutup dialog">×</button></div>${body}${footer?`<div class="form-actions">${footer}</div>`:""}</section></div>`;$("#modalClose").onclick=closeModal;$("#modalBackdrop").addEventListener("click",e=>{if(e.target.id==="modalBackdrop")closeModal()});}
function closeModal(){$("#modalRoot").innerHTML=""}
function subjectForm(index=null){const old=index===null?{name:"",semester:"Semester 1",year:state.profile.year||"2026/2027",grade:"",source:"Input manual"}:state.profile.subjects[index];openModal(index===null?"Tambah nilai":"Edit nilai",`<form id="subjectForm" class="form-grid"><div class="field full"><label for="subjectName">Mata pelajaran</label><select id="subjectName" required><option value="">Pilih mata pelajaran</option>${["Matematika","Bahasa Indonesia","Bahasa Inggris","Biologi","Kimia","Fisika","Informatika","Ekonomi","Sosiologi","Sejarah","Geografi","Seni Budaya","Lainnya"].map(s=>`<option ${old.name===s?"selected":""}>${s}</option>`).join("")}</select></div><div class="field"><label for="subjectSemester">Semester</label><select id="subjectSemester">${[1,2,3,4,5,6].map(n=>`<option ${old.semester===`Semester ${n}`?"selected":""}>Semester ${n}</option>`).join("")}</select></div><div class="field"><label for="subjectYear">Tahun ajaran</label><input id="subjectYear" required value="${escapeHtml(old.year)}" placeholder="2026/2027"></div><div class="field full"><label for="subjectGrade">Nilai (0–100)</label><input id="subjectGrade" type="number" min="0" max="100" step=".01" required value="${old.grade}" placeholder="Mis. 85"></div></form>`,`<button class="btn secondary" id="cancelSubject">Batal</button><button class="btn primary" id="saveSubject">Simpan nilai</button>`);$("#cancelSubject").onclick=closeModal;$("#saveSubject").onclick=()=>{const name=$("#subjectName").value,semester=$("#subjectSemester").value,year=$("#subjectYear").value.trim(),grade=Number($("#subjectGrade").value);if(!name||!year||$("#subjectGrade").value===""||!Number.isFinite(grade)||grade<0||grade>100){toast("Lengkapi semua kolom. Nilai harus 0–100.","error");return}const duplicate=state.profile.subjects.findIndex((s,i)=>s.name===name&&s.semester===semester&&s.year===year&&i!==index);if(duplicate>=0){toast("Nilai mata pelajaran, semester, dan tahun ajaran itu sudah ada.","error");return}const item={name,semester,year,grade,source:"Input manual"};if(index===null)state.profile.subjects.push(item);else state.profile.subjects[index]=item;saveState();logActivity(`${name} ${index===null?"ditambahkan":"diperbarui"} di Academic Profile`);closeModal();render();toast("Nilai berhasil disimpan.")}}
function showProgramDetail(id){
 const p=programById(id);if(!p)return;
 const row=(label,value)=>value!==null&&value!==undefined&&value!==""?`<tr><th>${escapeHtml(label)}</th><td>${escapeHtml(String(value))}</td></tr>`:"";
 const scoreAvailable=[p.scoreLow,p.scoreMid,p.scoreHigh].some(v=>v!==null&&v!==undefined&&v!=="");
 const weights=p.weights?Object.entries(p.weights).filter(([,v])=>v!==null&&v!==undefined&&v!=="").map(([k,v])=>`<tr><th>${escapeHtml(k.replace("_weight_pct","").replace("LBI","Literasi Bahasa Indonesia").replace("LBE","Literasi Bahasa Inggris").replace("PU","Penalaran Umum").replace("PPU","Pengetahuan dan Pemahaman Umum").replace("PBM","Pemahaman Bacaan dan Menulis").replace("PK","Pengetahuan Kuantitatif").replace("PM","Penalaran Matematika"))}</th><td>${escapeHtml(String(v))}%</td></tr>`).join(""):"";
 const body=`<p><strong>${escapeHtml(p.campus)}</strong> · ${escapeHtml(p.level)} · ${escapeHtml(p.field)}</p><div class="notice">Informasi berikut berasal dari dataset JALUR yang disertakan. Status verifikasi dan tahun referensi harus dibaca bersama datanya.</div><div class="table-wrap"><table class="data-table"><tbody>${row("Kode program studi",p.code)}${row("Bidang akademik",p.field)}${row("Kelompok disiplin",p.group)}${row("Status program studi",p.status)}${row("Akreditasi program studi",p.programAccreditation)}${row("Berlaku hingga (akreditasi prodi)",p.programAccreditationUntil)}${row("Akreditasi perguruan tinggi",p.institutionAccreditation)}${row("Berlaku hingga (akreditasi institusi)",p.institutionAccreditationUntil)}${row("Lokasi kampus",p.location)}${row("Kota/Kabupaten",p.city)}${row("Provinsi",p.province)}${row("Tahun referensi",p.referenceYear)}${row("Status verifikasi dataset",p.verification)}${row("Status estimasi skor",p.cutoffStatus)}${row("Tingkat keyakinan estimasi",p.scoreConfidence)}${row("Daya tampung SNBT",p.capacity)}${row("Jumlah pendaftar SNBT",p.applicants)}${row("Jumlah diterima SNBT",p.admitted)}</tbody></table></div>
 <h3>Informasi skor dan bobot simulasi</h3>${scoreAvailable?`<p>Rentang estimasi skor: ${escapeHtml(String(p.scoreLow??"—"))}–${escapeHtml(String(p.scoreHigh??"—"))}; nilai tengah ${escapeHtml(String(p.scoreMid??"—"))}. Data ini bukan ambang resmi dan hanya ditampilkan jika tersedia.</p>`:`<p>Belum tersedia skor penerimaan langsung per program studi yang tervalidasi. Kolom kosong tidak berarti skor nol atau peluang diterima nol.</p>`}
 ${weights?`<p>Profil bobot: <strong>${escapeHtml(p.weightProfile||"Simulasi")}</strong>. Bobot berikut adalah simulasi metodologis, bukan rumus resmi SNPMB.</p><div class="table-wrap"><table class="data-table"><tbody>${weights}</tbody></table></div><p>${escapeHtml(p.weightReason||"Bobot subtes tidak boleh dianggap sebagai bobot resmi.")}</p>`:""}
 ${p.source?`<p><a href="${escapeHtml(p.source)}" target="_blank" rel="noopener noreferrer">Buka sumber data program studi ↗</a></p>`:""}${p.website?`<p><a href="${escapeHtml(p.website)}" target="_blank" rel="noopener noreferrer">Situs perguruan tinggi ↗</a></p>`:""}${p.pddikti?`<p><a href="${escapeHtml(p.pddikti)}" target="_blank" rel="noopener noreferrer">Profil PDDikti ↗</a></p>`:""}
 <p class="source-line">${escapeHtml(p.scoreDisclaimer||"Pastikan memverifikasi informasi penerimaan, biaya, kurikulum, dan akreditasi melalui sumber resmi. JALUR tidak menjamin penerimaan.")}</p>`;
 openModal(escapeHtml(p.name),body,`<button class="btn secondary" id="detailClose">Tutup</button><button class="btn primary" id="detailCompare">${state.compared.includes(id)?"Sudah dibandingkan":"Tambahkan ke perbandingan"}</button>`);
 $("#detailClose").onclick=closeModal;$("#detailCompare").onclick=()=>{closeModal();addCompare(id)}
}
function addCompare(id){if(state.compared.includes(id)){toast("Program ini sudah ada di perbandingan.","info");return}if(state.compared.length>=4){toast("Perbandingan penuh. Hapus program lain terlebih dahulu.","error");return}state.compared.push(id);saveState();logActivity(`${programById(id).name} ditambahkan ke perbandingan`);render();toast("Program ditambahkan ke perbandingan.")}
function openProgramPicker(mode){
 const title=mode==="compare"?"Tambahkan program ke perbandingan":mode==="main"?"Pilih program utama":"Tambah alternatif";
 openModal(title,`<div class="field"><label for="pickerSearch">Cari program studi atau perguruan tinggi</label><input id="pickerSearch" type="search" placeholder="Ketik nama program atau institusi"></div><div class="field"><label for="pickerProgram">Hasil pencarian (maksimal 100 hasil)</label><select id="pickerProgram" size="7" style="width:100%"><option value="">Ketik kata kunci untuk mencari</option></select></div><p class="source-line">Pencarian menggunakan basis data JALUR yang disertakan. Pilih satu hasil untuk melanjutkan.</p>`,`<button class="btn secondary" id="pickerCancel">Batal</button><button class="btn primary" id="pickerConfirm">Tambahkan</button>`);
 const search=$("#pickerSearch"),select=$("#pickerProgram");
 const fill=()=>{
   const q=normalizeSearch(search.value);
   if(q.length<2){select.innerHTML='<option value="">Ketik minimal dua karakter</option>';return}
   const matches=programSearchIndex.filter(p=>matchesQuery(p._search,q)).slice(0,100);
   select.innerHTML=matches.length?matches.map(p=>`<option value="${escapeHtml(p.id)}">${escapeHtml(p.name)} — ${escapeHtml(p.campus)} (${escapeHtml(p.level||"")})</option>`).join(""):'<option value="">Tidak ada hasil</option>';
 };
 search.addEventListener("input",fill);
 $("#pickerCancel").onclick=closeModal;
 $("#pickerConfirm").onclick=()=>{
   const id=select.value;if(!id||!programById(id)){toast("Cari dan pilih program studi terlebih dahulu.","error");return}
   closeModal();
   if(mode==="compare")addCompare(id);
   else if(mode==="main"){
     const p=programById(id);const hidden=$("#mainProgram"),label=$("#mainProgramLabel");
     if(hidden&&label){hidden.value=id;label.textContent=`${p.name} — ${p.campus||"Perguruan tinggi tidak tercantum"}`;closeModal();}
   }else{
     if(id===state.mainChoice||state.alternatives.includes(id)){toast("Program itu sudah digunakan di Plan B.","error");return}
     if(state.alternatives.length>=3){toast("Maksimal 3 alternatif.","error");return}
     state.alternatives.push(id);saveState();logActivity(`${programById(id).name} ditambahkan sebagai alternatif`);render();toast("Alternatif ditambahkan.")
   }
 };
}

function selectedProgram(){return programById(state.mainChoice)||programs.find(p=>state.compared.includes(p.id))||null}
function programOptions(selected=""){return `<option value="">Pilih program studi</option>`+programs.slice().sort((a,b)=>alpha(a.name,b.name)||alpha(a.campus,b.campus)).slice(0,500).map(p=>`<option value="${escapeHtml(p.id)}" ${String(p.id)===String(selected)?"selected":""}>${escapeHtml(p.name)} — ${escapeHtml(p.campus||"Perguruan tinggi tidak tercantum")}</option>`).join("")}
function realityPage(){const p=selectedProgram();const program=p?`<div class="notice"><strong>${escapeHtml(p.name)}</strong> · ${escapeHtml(p.campus||"Perguruan tinggi tidak tercantum")}<br>Bidang: ${escapeHtml(p.field||"Belum diklasifikasikan")} · Jenjang: ${escapeHtml(p.level||"Tidak tercantum")}</div>`:`<div class="field"><label for="realityProgram">Pilih program studi dari basis data</label><select id="realityProgram">${programOptions()}</select></div>`;const field=p?.field||"bidang ini";const title=(p?.name||"Program studi pilihan");return `${pageHead("Program Study Reality Check","Pahami kegiatan belajar yang mungkin ditemui sebelum menetapkan pilihan.")}${program}<div class="notice"><strong>Status kurikulum: belum diverifikasi otomatis.</strong> Basis data JALUR terutama memuat identitas program dan perguruan tinggi. Rincian kurikulum khusus tiap program tidak tersedia secara merata; gunakan tautan sumber resmi untuk memeriksa kurikulum yang berlaku.</div><div class="program-grid"><article class="program-card glass"><span class="program-kicker">01 · KURIKULUM</span><h3>Mata kuliah</h3><p>Periksa kurikulum resmi ${escapeHtml(title)}. Catat mata kuliah dasar, mata kuliah inti, pilihan, dan tugas akhir.</p><a target="_blank" rel="noopener" href="https://pddikti.kemdiktisaintek.go.id/">Telusuri PDDikti ↗</a></article><article class="program-card glass"><span class="program-kicker">02 · METODE BELAJAR</span><h3>Kegiatan perkuliahan</h3><p>Identifikasi keseimbangan kuliah, diskusi, proyek kelompok, studi kasus, studio, praktik lapangan, atau praktikum dari sumber program yang dipilih.</p></article><article class="program-card glass"><span class="program-kicker">03 · KOMPETENSI</span><h3>Kemampuan yang dibutuhkan</h3><p>Perhatikan kemampuan analisis, komunikasi, pemecahan masalah, kerja tim, dan keterampilan khusus bidang ${escapeHtml(field)}. Kebutuhan nyata berbeda antarkurikulum.</p></article><article class="program-card glass"><span class="program-kicker">04 · REALITAS TUGAS</span><h3>Gambaran tugas</h3><p>Tanyakan kepada mahasiswa atau dosen tentang bentuk tugas, beban kerja mingguan, proyek, penilaian, dan dukungan belajar. Jangan menganggap contoh umum sebagai standar semua kampus.</p></article></div><section class="panel glass section-gap"><h2>Catatan eksplorasi</h2><div class="field full reality-note-field"><span class="field-label">Apa yang ingin kamu cari tahu lebih lanjut?</span><p class="help">Pilih topik pertanyaan. JALUR menyusun daftar pertanyaan tanpa perlu mengetik catatan bebas.</p>${choiceChecklist("realityQuestions",["Mata kuliah inti dan pilihan","Contoh tugas dan proyek","Praktikum atau praktik lapangan","Beban belajar mingguan","Cara penilaian dan ujian","Dukungan dosen dan penasihat akademik","Magang dan prospek karier","Biaya, beasiswa, dan bantuan pendidikan"],state.notes.realityChoices||[])}<small class="help">Pilihan ini ikut tersimpan pada profilmu setelah login siswa.</small></div><div class="form-actions"><button class="btn primary" id="saveReality">Simpan catatan</button><a class="btn secondary" target="_blank" rel="noopener" href="https://snpmb.id/">Periksa sumber resmi ↗</a></div></section>`}
function similarityPage(){const base=selectedProgram();const q=base?base.name:"";const candidates=base?programs.filter(p=>String(p.id)!==String(base.id)).map(p=>{let score=0;const a=String(base.field||base.group||"").toLowerCase(),b=String(p.field||p.group||"").toLowerCase();if(a&&b&&a===b)score+=3;const words=x=>String(x||"").toLowerCase().split(/[^a-z0-9]+/).filter(w=>w.length>3);const overlap=words(base.name).filter(w=>words(p.name).includes(w)).length;score+=overlap*2;if(base.level&&p.level===base.level)score+=1;return {p,score}}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,30):[];return `${pageHead("Similarity Explorer","Temukan program lain yang dapat dipertimbangkan sebagai pembanding.")}${base?`<div class="notice">Program acuan: <strong>${escapeHtml(base.name)}</strong> · ${escapeHtml(base.campus||"Perguruan tinggi tidak tercantum")}</div>`:`<div class="field"><label for="similarityProgram">Pilih program acuan</label><select id="similarityProgram">${programOptions()}</select></div><p class="source-line">Tetapkan pilihan utama pada menu Rencana Alternatif atau pilih program di Perbandingan, lalu buka kembali fitur ini.</p>`}<div class="notice">Kemiripan dihitung secara sederhana dari kesamaan nama, kelompok/bidang, dan jenjang yang tercatat dalam basis data. Karena data mata kuliah dan kompetensi tidak tersedia merata, hasil ini bukan penilaian akademik menyeluruh.</div>${candidates.length?`<div class="program-grid">${candidates.map(({p,score})=>`<article class="program-card glass"><span class="program-kicker">KEMIRIPAN INDIKATIF · ${score} POIN</span><h3>${escapeHtml(p.name)}</h3><p class="campus">${escapeHtml(p.campus||"Perguruan tinggi tidak tercantum")}</p><p>${escapeHtml(p.field||p.group||"Bidang belum tercatat")} · ${escapeHtml(p.level||"Jenjang tidak tercantum")}</p><button class="btn secondary" data-compare="${escapeHtml(p.id)}">Tambahkan ke perbandingan</button></article>`).join("")}</div>`:`<section class="panel glass"><h2>Mulai dari program pilihan</h2><p>Pilih program acuan dengan menetapkannya di menu Rencana Alternatif atau tambahkan beberapa program ke Perbandingan.</p><button class="btn primary" data-page="Study Program Explorer">Buka basis data program studi</button></section>`}`}
function pathwayPage(){const all=programs.filter(p=>[state.mainChoice,...state.alternatives].includes(p.id));return `${pageHead("Alternative Pathway Planner","Kelompokkan pilihan agar rencana pendidikan tidak bergantung pada satu program saja.")}${panel("Pilihan dalam rencana",all.length?`<div class="program-grid">${all.map(p=>`<article class="program-card glass"><h3>${escapeHtml(p.name)}</h3><p>${escapeHtml(p.campus||"Perguruan tinggi tidak tercantum")}</p><label for="path-${escapeHtml(p.id)}">Kelompok pilihan</label><select data-pathway="${escapeHtml(p.id)}" id="path-${escapeHtml(p.id)}"><option value="utama" ${(state.pathwayGroups[p.id]|| (p.id===state.mainChoice?"utama":"sejalur"))==="utama"?"selected":""}>Pilihan utama</option><option value="sejalur" ${(state.pathwayGroups[p.id]|| (p.id===state.mainChoice?"utama":"sejalur"))==="sejalur"?"selected" :""}>Alternatif sejalur</option><option value="lainnya" ${state.pathwayGroups[p.id]==="lainnya"?"selected":""}>Alternatif bidang lain</option></select></article>`).join("")}</div>`:`<p>Belum ada program dalam rencana. Pilih program utama dan tambahkan alternatif dari Penjelajah Program Studi.</p><button class="btn primary" data-page="Plan B Builder">Susun pilihan</button>`)}<section class="panel glass section-gap"><h2>Prinsip penyusunan alternatif</h2><ul><li>Pastikan setiap pilihan sesuai minat dan kesiapan akademik.</li><li>Periksa persyaratan dan jalur penerimaan setiap program secara terpisah.</li><li>Bandingkan biaya, lokasi, kurikulum, dan dukungan yang tersedia.</li><li>Jangan menganggap alternatif sebagai jaminan diterima.</li></ul><button class="btn primary" id="savePathways">Simpan pengelompokan</button></section>`}
function campusPage(){const p=selectedProgram();const inst=p?institutions.find(i=>String(i.id)===String(p.institutionId)):null;return `${pageHead("Campus Life Preview","Susun gambaran kehidupan kampus berdasarkan informasi yang dapat diverifikasi.")}${p?`<div class="notice">Pilihan saat ini: <strong>${escapeHtml(p.name)}</strong> · ${escapeHtml(p.campus||"Perguruan tinggi tidak tercantum")}</div>`:`<p>Pilih program utama atau program pada menu Perbandingan untuk menampilkan institusi terkait.</p>`}<div class="program-grid"><article class="program-card glass"><span class="program-kicker">FASILITAS</span><h3>Fasilitas kampus</h3><p>Periksa perpustakaan, laboratorium, ruang belajar, aksesibilitas, layanan kesehatan, dan fasilitas yang relevan melalui situs resmi kampus.</p>${inst?.website?`<a target="_blank" rel="noopener" href="${escapeHtml(inst.website)}">Situs perguruan tinggi ↗</a>`:`<a target="_blank" rel="noopener" href="https://pddikti.kemdiktisaintek.go.id/">Cari informasi institusi ↗</a>`}</article><article class="program-card glass"><span class="program-kicker">KEMAHASISWAAN</span><h3>Organisasi dan kegiatan</h3><p>Telusuri organisasi mahasiswa, unit kegiatan, komunitas akademik, kegiatan relawan, dan layanan pengembangan diri.</p></article><article class="program-card glass"><span class="program-kicker">LINGKUNGAN</span><h3>Lingkungan belajar</h3><p>Bandingkan lokasi, transportasi, pilihan tempat tinggal, akses internet, dan dukungan belajar. Konfirmasikan kondisi terkini kepada kampus.</p></article></div><section class="panel glass section-gap"><h2>Daftar pertanyaan untuk kampus</h2><p class="panel-sub">Pilih pertanyaan yang ingin disampaikan kepada pihak kampus.</p>${choiceChecklist("campusQuestions",["Apakah tersedia laboratorium dan peralatan praktik yang memadai?","Organisasi dan kegiatan mahasiswa apa yang aktif?","Bagaimana pilihan transportasi dan akses ke kampus?","Apakah tersedia asrama atau rekomendasi tempat tinggal?","Bagaimana layanan konseling dan dukungan akademik?","Apa saja beasiswa dan bantuan biaya yang tersedia?","Bagaimana peluang magang dan kerja sama industri?","Bagaimana mekanisme konsultasi dengan dosen wali?"],state.notes.campusChoices||[])}<button class="btn primary" id="saveCampus">Simpan daftar pertanyaan</button></section>`}
function costPage(){const c=state.costPlans||{};const keys=[['tuition','Uang kuliah per semester'],['housing','Tempat tinggal per bulan'],['transport','Transportasi per bulan'],['food','Makan dan kebutuhan harian per bulan'],['study','Kebutuhan perkuliahan per semester'],['other','Biaya lain per bulan']];const monthly=['housing','transport','food','other'];const total=keys.reduce((sum,[k])=>sum+Math.max(0,Number(c[k])||0)*(monthly.includes(k)?12:2),0);return `${pageHead("Education Cost Planner","Perkirakan kebutuhan biaya berdasarkan masukanmu sendiri; angka tidak diambil otomatis dari tarif kampus.")}${panel("Masukkan perkiraan biaya",`<div class="form-grid">${keys.map(([k,label])=>`<div class="field"><label for="cost-${k}">${label} (Rp)</label><input id="cost-${k}" data-cost="${k}" type="number" min="0" step="1000" value="${escapeHtml(c[k]??"")}" placeholder="0"></div>`).join("")}</div><p class="source-line">Estimasi ilustratif dua semester: biaya bulanan dikalikan 12 dan biaya per semester dikalikan 2. Tidak termasuk inflasi, uang pangkal, beasiswa, atau biaya tak terduga kecuali kamu memasukkannya.</p><div class="summary-block"><span class="eyebrow">PERKIRAAN TAHUNAN</span><h2>Rp ${Math.round(total).toLocaleString("id-ID")}</h2><p>Perkiraan berdasarkan angka yang diisikan.</p></div><button class="btn primary" id="saveCosts">Simpan perkiraan</button>`)}<section class="panel glass section-gap"><h2>Verifikasi biaya</h2><p>Gunakan laman resmi kampus untuk memeriksa UKT, biaya awal, skema cicilan, beasiswa, dan ketentuan bantuan biaya pendidikan. Jangan menganggap nilai masukan sebagai tarif resmi.</p><a class="btn secondary" target="_blank" rel="noopener" href="https://kip-kuliah.kemdiktisaintek.go.id/">Informasi KIP Kuliah ↗</a></section>`}
function journalPage(){const entries=state.journal||[];return `${pageHead("Decision Journal & Reflection","Catat alasan, keraguan, dan perubahan pertimbangan selama mengeksplorasi pendidikan tinggi.")}<section class="panel glass"><h2>Catatan baru</h2><form id="journalForm" class="form-grid"><div class="field"><label for="journalType">Jenis catatan</label><select id="journalType"><option>Alasan memilih</option><option>Keraguan</option><option>Perubahan preferensi</option><option>Hasil pertimbangan</option><option>Hal yang perlu diverifikasi</option></select></div><div class="field"><label for="journalProgram">Program studi (opsional)</label><select id="journalProgram">${programOptions()}</select></div><div class="field full"><span class="field-label">Aspek refleksi (pilih minimal satu)</span>${choiceChecklist("journalPrompts",["Saya makin yakin dengan pilihan ini","Saya masih memiliki keraguan","Saya menemukan informasi baru","Ada hal penting yang perlu diverifikasi","Preferensi saya berubah","Saya perlu berdiskusi dengan guru BK atau keluarga","Saya ingin membandingkan alternatif lain"],[])}</div><div class="field full"><button class="btn primary" type="submit">Simpan catatan</button></div></form></section><section class="panel glass section-gap"><div class="panel-head"><h2>Riwayat refleksi</h2><span class="panel-sub">${entries.length} catatan</span></div>${entries.length?entries.slice(-100).reverse().map((e,i)=>`<article class="program-card glass"><span class="program-kicker">${escapeHtml(e.type)} · ${escapeHtml(e.date)}</span><h3>${escapeHtml(e.program||"Catatan umum")}</h3><p>${escapeHtml(e.text)}</p><button class="text-btn" data-delete-journal="${entries.length-1-i}">Hapus catatan</button></article>`).join(""):`<p>Belum ada catatan. Catatan akan tersimpan secara lokal pada peramban ini.</p>`}</section>`}

const PORTAL_KEY="jalur-role-workflows-v1";
function portalData(){try{return JSON.parse(localStorage.getItem(PORTAL_KEY)||'{"consultations":[],"vents":[],"students":[],"teachers":[],"classes":[],"subjects":[],"grades":[],"alumni":[]}')}catch{return {consultations:[],vents:[],students:[],teachers:[],classes:[],subjects:[],grades:[],alumni:[]}}}
function savePortalData(d){localStorage.setItem(PORTAL_KEY,JSON.stringify(d))}
function safeText(v){return escapeHtml(String(v??""))}
function consultationPage(){const d=portalData();return `${pageHead("BK Consultation","Ajukan sesi dengan guru BK. Isi seperlunya; hindari menuliskan informasi sangat sensitif pada perangkat bersama.")}<div class="notice"><strong>Privasi:</strong> pada versi ini permintaan hanya tersimpan di browser/perangkat ini. Belum terkirim ke sekolah atau guru BK. Jangan gunakan untuk keadaan darurat.</div><section class="panel glass"><h2>Ajukan konsultasi</h2><form id="consultForm" class="form-grid"><div class="field"><label for="consultName">Nama / nama panggilan</label><input id="consultName" required maxlength="70" placeholder="Nama yang dapat dikenali guru BK"></div><div class="field"><label for="consultClass">Kelas</label><input id="consultClass" required maxlength="30" placeholder="Contoh: XI IPA 2"></div><div class="field"><label for="consultDate">Tanggal yang diinginkan</label><input id="consultDate" type="date" required min="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label for="consultTime">Waktu yang diinginkan</label><select id="consultTime" required><option value="">Pilih waktu</option><option>08.00–09.00</option><option>09.00–10.00</option><option>10.00–11.00</option><option>11.00–12.00</option><option>13.00–14.00</option><option>14.00–15.00</option></select></div><div class="field"><label for="consultMode">Metode</label><select id="consultMode"><option>Tatap muka</option><option>Daring</option></select></div><div class="field"><label for="consultTopic">Topik umum</label><select id="consultTopic"><option>Akademik</option><option>Rencana studi lanjut</option><option>Relasi pertemanan</option><option>Motivasi dan kebiasaan belajar</option><option>Kesejahteraan diri</option><option>Lainnya</option></select></div><div class="field full"><label for="consultContext">Hal yang ingin disampaikan (opsional)</label><select id="consultContext"><option value="">Tidak ada keterangan tambahan</option><option>Ingin membahas pilihan studi lanjut</option><option>Ingin membahas kesulitan akademik</option><option>Ingin membahas relasi sosial</option><option>Ingin mendapat dukungan belajar</option><option>Ingin membahas kesejahteraan diri</option><option>Perlu bantuan menentukan langkah berikutnya</option></select></div><div class="field full"><button class="btn primary" type="submit">Simpan permintaan konsultasi</button></div></form></section><section class="panel glass section-gap"><div class="panel-head"><h2>Permintaan pada perangkat ini</h2><span class="panel-sub">${d.consultations.length} permintaan</span></div>${d.consultations.length?d.consultations.slice().reverse().map((c,i)=>`<article class="program-card glass"><span class="program-kicker">${safeText(c.date)} · ${safeText(c.time)}</span><h3>${safeText(c.name)} — ${safeText(c.topic)}</h3><p>${safeText(c.className)} · ${safeText(c.mode)}</p><p>Status: <strong>${safeText(c.status)}</strong></p>${c.note?`<p>${safeText(c.note)}</p>`:""}<button class="text-btn" data-delete-consult="${d.consultations.length-1-i}">Hapus permintaan</button></article>`).join(""):`<div class="empty-state"><h3>Belum ada permintaan</h3><p>Permintaan yang dibuat akan muncul di sini pada browser ini.</p></div>`}</section>`}
function ventingPage(){const d=portalData();return `${pageHead("Anonymous Venting","Ruang menulis perasaan tanpa memasukkan nama. Kamu boleh menulis singkat atau sekadar menyusun pikiran.")}<div class="notice"><strong>Penting:</strong> ini belum menjadi layanan anonim daring. Catatan disimpan di browser ini dan dapat dilihat orang yang memakai perangkat yang sama. Jangan masukkan nama, alamat, kata sandi, atau informasi yang dapat mengidentifikasi seseorang.</div><section class="panel glass"><h2>Tulis curahan hati</h2><form id="ventForm" class="form-grid"><div class="field"><label for="ventMood">Apa yang paling terasa sekarang?</label><select id="ventMood"><option>Terbebani</option><option>Cemas</option><option>Sedih</option><option>Bingung</option><option>Kesepian</option><option>Marah</option><option>Lega</option><option>Belum tahu</option></select></div><div class="field"><label for="ventCategory">Topik (opsional)</label><select id="ventCategory"><option>Akademik</option><option>Keluarga</option><option>Teman</option><option>Masa depan</option><option>Keadaan diri</option><option>Lainnya</option></select></div><div class="field full"><span class="field-label">Hal yang sedang kamu alami (pilih satu atau beberapa)</span>${choiceChecklist("ventTopics",["Tugas atau beban akademik","Kebingungan tentang masa depan","Tekanan dari lingkungan sekitar","Kesulitan mengatur waktu","Masalah relasi atau pertemanan","Kondisi keluarga","Merasa lelah dan membutuhkan jeda","Ingin mencari bantuan dari orang tepercaya"],[])}<small class="help">Tidak perlu menuliskan nama atau informasi yang dapat mengidentifikasi siapa pun.</small></div><div class="field full"><label class="check-item"><input type="checkbox" id="ventSupport"><span><strong>Saya ingin mempertimbangkan berbicara dengan guru BK.</strong><p>Ini hanya penanda pribadi, bukan pengiriman pesan otomatis.</p></span></label></div><div class="field full"><button class="btn primary" type="submit">Simpan catatan di perangkat ini</button></div></form></section><section class="panel glass section-gap"><h2>Catatan pribadi</h2>${d.vents.length?d.vents.slice().reverse().map((v,i)=>`<article class="program-card glass"><span class="program-kicker">${safeText(v.date)} · ${safeText(v.mood)}</span><h3>${safeText(v.category)}</h3><p style="white-space:pre-wrap">${safeText(v.text)}</p>${v.support?`<p>Penanda pribadi: ingin mempertimbangkan konsultasi BK.</p>`:""}<button class="text-btn" data-delete-vent="${d.vents.length-1-i}">Hapus catatan</button></article>`).join(""):`<p>Catatan yang kamu simpan akan tampil di sini.</p>`}</section><p class="source-line">Jika kamu merasa tidak aman atau membutuhkan bantuan segera, hubungi orang dewasa tepercaya atau layanan darurat setempat. Curhat ini bukan layanan pemantauan waktu nyata.</p>`}
function schoolPortalPage(){const d=portalData();const fields=[['students','Siswa','studentName','Nama siswa'],['teachers','Guru','teacherName','Nama guru'],['classes','Kelas','classNameInput','Nama kelas'],['subjects','Mata pelajaran','subjectName','Nama mata pelajaran'],['alumni','Data alumni','alumniName','Nama alumni']];return `${pageHead("School Portal","Kelola data dasar yang menunjang pengalaman JALUR. Portal ini saat ini berjalan lokal dan belum memiliki autentikasi server.",`<button class="btn secondary small" data-return-welcome>Kembali ke halaman pembuka</button>`)}<div class="notice"><strong>Jangan masukkan data nyata yang sensitif.</strong> Ini adalah mekanisme kerja lokal untuk diuji, bukan portal sekolah aman. Sebelum digunakan sekolah, wajib ditambahkan login server, izin per peran, audit log, cadangan, dan database terpusat.</div><section class="panel glass"><h2>Data sekolah</h2><div class="portal-tabs">${fields.map(([key,label])=>`<button class="btn secondary small" data-school-tab="${key}">${label} (${d[key].length})</button>`).join("")}<button class="btn secondary small" data-school-tab="grades">Nilai rapor (${d.grades.length})</button></div><form id="schoolRecordForm" class="form-grid section-gap"><div class="field"><label for="schoolDataType">Jenis data</label><select id="schoolDataType">${fields.map(([key,label])=>`<option value="${key}">${label}</option>`).join("")}<option value="grades">Nilai rapor</option></select></div><div class="field"><label for="schoolRecordName">Nama / identitas data</label><input id="schoolRecordName" required maxlength="120" placeholder="Nama atau label data"></div><div class="field"><label for="schoolRecordDetail">Keterangan</label><input id="schoolRecordDetail" maxlength="240" placeholder="Contoh: kelas, mata pelajaran, tahun lulus"></div><div class="field"><label for="schoolRecordValue">Nilai (khusus rapor, opsional)</label><input id="schoolRecordValue" type="number" min="0" max="100" step="0.01" placeholder="0–100"></div><div class="field full"><button class="btn primary" type="submit">Simpan data</button></div></form></section><section class="panel glass section-gap"><div class="panel-head"><h2>Data tersimpan di perangkat ini</h2><button class="btn secondary small" id="exportSchoolData">Ekspor JSON</button></div><div id="schoolRecordList">${schoolList(d,"students")}</div></section>`}
function schoolList(d,key){const labels={students:"Siswa",teachers:"Guru",classes:"Kelas",subjects:"Mata pelajaran",alumni:"Alumni",grades:"Nilai rapor"};const arr=d[key]||[];return `<h3>${labels[key]||key} (${arr.length})</h3>${arr.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Nama / identitas</th><th>Keterangan</th><th>Nilai</th><th>Aksi</th></tr></thead><tbody>${arr.map((x,i)=>`<tr><td>${safeText(x.name)}</td><td>${safeText(x.detail||"—")}</td><td>${x.value??"—"}</td><td><button class="text-btn" data-delete-school="${key}:${i}">Hapus</button></td></tr>`).join("")}</tbody></table></div>`:`<p>Belum ada data ${labels[key]||key.toLowerCase()}.</p>`}`}
function bkPortalPage(){const d=portalData();return `${pageHead("BK Portal","Kelola permintaan konsultasi dan tinjau catatan curhat yang disimpan pada browser yang sama.",`<button class="btn secondary small" data-return-welcome>Kembali ke halaman pembuka</button>`)}<div class="notice"><strong>Batas akses:</strong> daftar ini bukan kotak masuk daring. Guru BK tidak akan menerima data dari perangkat siswa lain sampai backend aman dan kanal pengiriman dibuat.</div><section class="panel glass"><h2>Permintaan konsultasi (${d.consultations.length})</h2>${d.consultations.length?d.consultations.slice().reverse().map((c,i)=>`<article class="program-card glass"><span class="program-kicker">${safeText(c.date)} · ${safeText(c.time)}</span><h3>${safeText(c.name)} — ${safeText(c.topic)}</h3><p>${safeText(c.className)} · ${safeText(c.mode)}</p><p>${safeText(c.note||"Tanpa catatan tambahan")}</p><label for="bkstatus-${i}">Status</label><select id="bkstatus-${i}" data-consult-status="${d.consultations.length-1-i}"><option ${c.status==="Menunggu konfirmasi"?"selected":""}>Menunggu konfirmasi</option><option ${c.status==="Dikonfirmasi"?"selected":""}>Dikonfirmasi</option><option ${c.status==="Dijadwalkan ulang"?"selected":""}>Dijadwalkan ulang</option><option ${c.status==="Selesai"?"selected":""}>Selesai</option><option ${c.status==="Dibatalkan"?"selected":""}>Dibatalkan</option></select></article>`).join(""):`<p>Belum ada permintaan konsultasi di browser ini.</p>`}</section><section class="panel glass section-gap"><h2>Curhat anonim tersimpan lokal (${d.vents.length})</h2><p class="source-line">Hanya untuk menguji alur pada perangkat yang sama. Jangan gunakan untuk memantau siswa atau menangani krisis.</p>${d.vents.length?d.vents.slice().reverse().map(v=>`<article class="program-card glass"><span class="program-kicker">${safeText(v.date)} · ${safeText(v.mood)}</span><h3>${safeText(v.category)}</h3><p style="white-space:pre-wrap">${safeText(v.text)}</p></article>`).join(""):`<p>Belum ada catatan lokal.</p>`}</section>`}

function openDrawer(){ $("#drawerBackdrop").classList.remove("hidden");$("#drawerBackdrop").innerHTML=`<div class="mobile-drawer" role="dialog" aria-label="Menu lainnya"><h3>Menu lainnya <button class="text-btn" id="closeDrawer" style="float:right">Tutup ×</button></h3>${["Academic Profile","Program Study Reality Check","Similarity Explorer","Alternative Pathway Planner","Campus Life Preview","Education Cost Planner","Decision Journal","BK Consultation","Anonymous Venting","Study Tracer Alumni","Decision Blind Spot Detector","Decision Summary","Settings","Help / About","User Guide","Official Sources"].map(p=>`<button class="${p===currentPage?"active":""}" data-drawer-page="${p}">${PAGE_LABELS[p]||p}</button>`).join("")}</div>`;$("#closeDrawer").onclick=closeDrawer;$$("[data-drawer-page]").forEach(b=>b.onclick=()=>{closeDrawer();navigate(b.dataset.drawerPage)});$("#drawerBackdrop").onclick=e=>{if(e.target.id==="drawerBackdrop")closeDrawer()}}
function closeDrawer(){$("#drawerBackdrop").classList.add("hidden");$("#drawerBackdrop").innerHTML=""}
function navigate(page){if(page==="School Portal"&&activeRole!=="school"){toast("Portal pengelola hanya tersedia melalui jalur masuk sekolah.","error");return}if(page==="BK Portal"&&activeRole!=="bk"){toast("Portal BK hanya tersedia melalui jalur masuk guru BK.","error");return}currentPage=page;state.currentPage=page;saveState();render();window.scrollTo({top:0,behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"})}
