document.addEventListener("submit",async e=>{
 if(e.target.id==="schoolGateForm"||e.target.id==="bkGateForm"){e.preventDefault();const role=e.target.id==="schoolGateForm"?"school":"bk";const code=(role==="school"?$("#schoolCode").value:$("#bkCode").value).trim();const key="jalur-local-role-gates";let gates={};try{gates=JSON.parse(localStorage.getItem(key)||"{}")}catch{};if(!gates[role]){gates[role]=code;localStorage.setItem(key,JSON.stringify(gates));}else if(gates[role]!==code){toast("Kode uji lokal tidak cocok dengan kode yang dibuat pada browser ini.","error");return;}closeModal();activeRole=role;$("#welcome").classList.add("hidden");$("#app").classList.remove("hidden");navigate(role==="school"?"School Portal":"BK Portal");toast("Portal uji lokal dibuka. Ini bukan autentikasi produksi.","info");return;}
 if(e.target.id==="consultForm"){e.preventDefault();const d=portalData();const date=$("#consultDate").value,time=$("#consultTime").value,name=$("#consultName").value.trim();if(d.consultations.some(c=>c.date===date&&c.time===time&&c.name===name&&c.status!=="Dibatalkan")){toast("Permintaan dengan tanggal, waktu, dan nama tersebut sudah ada.","error");return;}d.consultations.push({name,className:$("#consultClass").value.trim(),date,time,mode:$("#consultMode").value,topic:$("#consultTopic").value,note:$("#consultContext").value,status:"Menunggu konfirmasi",createdAt:new Date().toISOString()});savePortalData(d);render();toast("Permintaan disimpan pada browser ini. Guru BK belum menerima notifikasi.","info");return;}
 if(e.target.id==="ventForm"){e.preventDefault();const d=portalData(),topics=readChoices("ventTopics");if(!topics.length){toast("Pilih minimal satu topik agar catatan terstruktur bermakna.","error");return;}d.vents.push({mood:$("#ventMood").value,category:$("#ventCategory").value,text:"Topik yang ingin dicatat: "+topics.join("; ")+".",support:$("#ventSupport").checked,date:new Date().toLocaleString("id-ID",{dateStyle:"medium",timeStyle:"short"})});savePortalData(d);render();toast("Catatan terstruktur disimpan lokal di perangkat ini.","info");return;}
 if(e.target.id==="schoolRecordForm"){e.preventDefault();const d=portalData(),key=$("#schoolDataType").value,name=$("#schoolRecordName").value.trim(),detail=$("#schoolRecordDetail").value.trim(),value=$("#schoolRecordValue").value;d[key].push({name,detail,value:key==="grades"&&value!==""?Number(value):null,createdAt:new Date().toISOString()});savePortalData(d);render();toast("Data ditambahkan pada browser ini.","info");return;}
 if(e.target.id==="alumniNoteForm"){e.preventDefault();const program=$("#alumniProgram").value.trim(),source=$("#alumniSource").value,findings=readChoices("alumniFindings");if(!findings.length){toast("Pilih minimal satu temuan wawancara.","error");return}state.journal.push({type:"Temuan pengalaman",program:program||"Catatan pengalaman",text:`Sumber: ${source}. Hal yang dikonfirmasi: ${findings.join("; ")}.`,date:new Date().toLocaleString("id-ID",{dateStyle:"medium",timeStyle:"short"})});saveState();logActivity("Temuan pengalaman disimpan ke jurnal");navigate("Decision Journal");toast("Temuan terstruktur disimpan ke Jurnal Keputusan.");return}
 if(e.target.id==="journalForm"){e.preventDefault();const picks=readChoices("journalPrompts");if(!picks.length){toast("Pilih minimal satu aspek refleksi.","error");return;}const text="Refleksi terstruktur: "+picks.join("; ")+ ".";const entry={type:$("#journalType").value,program:programById($("#journalProgram").value)?.name||"",text,date:new Date().toLocaleString("id-ID",{dateStyle:"medium",timeStyle:"short"})};try{const remote=window.JALUR_API?.getUser?.();if(remote){await window.JALUR_API.request("/journal",{method:"POST",body:{type:entry.type,program:entry.program,text:entry.text}});const saved=await window.JALUR_API.request("/journal");state.journal=saved.items||[];}else{state.journal.push(entry);}saveState();logActivity("Jurnal keputusan diperbarui");render();toast("Refleksi terstruktur disimpan.");}catch(err){toast(err.message||"Refleksi gagal disimpan.","error");}}
 if(e.target.id==="profileForm"){e.preventDefault();state.profile.nickname=$("#nickname").value.trim();state.profile.grade=$("#grade").value;state.profile.year=$("#year").value.trim();saveState();logActivity("Academic Profile diperbarui");render();toast("Profil berhasil disimpan sementara.");}
 if(e.target.id==="subjectForm")e.preventDefault();
 if(e.target.id==="mainChoiceForm"){e.preventDefault();const id=$("#mainProgram").value,reasons=readChoices("mainReasons"),reason=reasons.join(" · ");if(!id||!reasons.length){toast("Pilih program dan minimal satu alasan.","error");return}state.mainChoice=id;state.notes.mainReason=reason;state.notes.mainReasonChoices=reasons;state.notes.mainCriteria=$("#mainCriteria").value;saveState();logActivity(`${programById(id).name} ditetapkan sebagai pilihan utama`);render();toast("Pilihan utama diperbarui.");}
});
document.addEventListener("change",e=>{
 if(e.target.matches("[data-consult-status]")){const d=portalData();d.consultations[Number(e.target.dataset.consultStatus)].status=e.target.value;savePortalData(d);toast("Status diperbarui pada browser ini.","info");return;}
 if(["searchScope","fieldFilter","levelFilter","provinceFilter"].includes(e.target.id)){window.explorerQuery=$("#programSearch")?.value||"";window.explorerScope=$("#searchScope")?.value||"Semua hasil";window.explorerField=$("#fieldFilter")?.value||"Semua bidang";window.explorerLevel=$("#levelFilter")?.value||"Semua jenjang";window.explorerProvince=$("#provinceFilter")?.value||"Semua provinsi";window.explorerLimit=30;render();return}
 if(e.target.id==="importSample"){return}
 if(e.target.id==="realityProgram"||e.target.id==="similarityProgram"){const p=programById(e.target.value);if(p){state.mainChoice=p.id;saveState();render()}return}
 if(e.target.id==="importDataFile"){const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const payload=JSON.parse(String(reader.result||""));if(payload.app!=="JALUR"||!payload.state||!payload.state.profile||!Array.isArray(payload.state.profile.subjects))throw new Error("format");if(!confirm("Pulihkan cadangan ini? Data JALUR yang sekarang tersimpan akan digantikan.")){e.target.value="";return}state={...structuredClone(initialState),...payload.state};saveState();render();toast("Cadangan berhasil dipulihkan.")}catch(err){toast("Berkas tidak sesuai dengan format cadangan JALUR.","error")}e.target.value=""};reader.readAsText(file);return}
 if(e.target.id==="largeText"){state.settings.largeText=e.target.checked;document.body.style.fontSize=e.target.checked?"17px":"";saveState()}
 if(e.target.id==="reduceMotion"){state.settings.reduceMotion=e.target.checked;document.documentElement.style.scrollBehavior=e.target.checked?"auto":"";saveState()}
 if(e.target.matches("[data-check-spot]")){const i=Number(e.target.dataset.checkSpot);if(e.target.checked&&!state.checked.includes(i))state.checked.push(i);if(!e.target.checked)state.checked=state.checked.filter(x=>x!==i);saveState();render();toast(e.target.checked?"Aspek ditandai sudah diperiksa.":"Tanda pemeriksaan dibatalkan.","info")}
});
document.addEventListener("input",e=>{
 if(["programSearch","searchScope","fieldFilter","levelFilter","provinceFilter"].includes(e.target.id)){window.explorerQuery=$("#programSearch")?.value||"";window.explorerScope=$("#searchScope")?.value||"Semua hasil";window.explorerField=$("#fieldFilter")?.value||"Semua bidang";window.explorerLevel=$("#levelFilter")?.value||"Semua jenjang";window.explorerProvince=$("#provinceFilter")?.value||"Semua provinsi";window.explorerLimit=30;const active=document.activeElement?.id;const pos=active==="programSearch"?$("#programSearch").selectionStart:null;const root=$("#pageRoot");root.innerHTML=explorerPage();if(active==="programSearch"){$("#programSearch").focus();if(pos!==null)$("#programSearch").setSelectionRange(pos,pos)}return}
 if(e.target.id==="alumniSearch"){$$(".alumni-card").forEach(card=>card.style.display=card.dataset.search.includes(e.target.value.toLowerCase())?"flex":"none")}
});
document.addEventListener("click",async e=>{
 const copyQuestion=e.target.closest("[data-copy-question]");if(copyQuestion){const qs=[["Kegiatan belajar","Seperti apa satu minggu perkuliahan yang umum? Berapa banyak kuliah, proyek, diskusi, praktikum, atau tugas mandiri?"],["Tugas dan tantangan","Tugas apa yang paling sering ditemui? Kemampuan apa yang ternyata paling dibutuhkan?"],["Dukungan kampus","Bagaimana akses ke dosen, penasihat akademik, layanan konseling, beasiswa, dan fasilitas belajar?"],["Kehidupan sehari-hari","Bagaimana transportasi, tempat tinggal, organisasi, biaya hidup, dan keseimbangan waktu?"],["Refleksi pilihan","Apa yang ingin diketahui sebelum masuk? Apa yang akan disarankan untuk calon mahasiswa?"]];const q=qs[Number(copyQuestion.dataset.copyQuestion)];if(q){if(navigator.clipboard?.writeText){navigator.clipboard.writeText(q[1]).then(()=>toast("Pertanyaan berhasil disalin."),()=>openModal("Salin pertanyaan",`<div class="question-preview" role="note">${escapeHtml(q[1])}</div>`))}else openModal("Salin pertanyaan",`<div class="question-preview" role="note">${escapeHtml(q[1])}</div>`)}return}
 const campusSearch=e.target.closest("[data-search-campus]");if(campusSearch){window.explorerQuery=campusSearch.dataset.searchCampus||"";window.explorerScope="Program studi";window.explorerField="Semua bidang";window.explorerLevel="Semua jenjang";window.explorerProvince="Semua provinsi";window.explorerLimit=30;render();return}
 if(e.target.id==="searchInstitutions"){searchInstitutions();return}
 if(e.target.id==="saveReality"){const values=readChoices("realityQuestions");if(!values.length){toast("Pilih minimal satu topik eksplorasi.","error");return;}state.notes.realityChoices=values;state.notes.reality=values.join(" · ");saveState();toast("Daftar eksplorasi disimpan.");return}
 if(e.target.id==="saveCampus"){const values=readChoices("campusQuestions");if(!values.length){toast("Pilih minimal satu pertanyaan untuk kampus.","error");return;}state.notes.campusChoices=values;state.notes.campus=values.join(" · ");saveState();toast("Daftar pertanyaan kampus disimpan.");return}
 if(e.target.id==="saveCosts"){state.costPlans={};$$('[data-cost]').forEach(el=>state.costPlans[el.dataset.cost]=Math.max(0,Number(el.value)||0));saveState();render();toast("Perkiraan biaya disimpan.");return}
 if(e.target.id==="savePathways"){ $$('[data-pathway]').forEach(el=>state.pathwayGroups[el.dataset.pathway]=el.value);saveState();toast("Pengelompokan pilihan disimpan.");return}
 const delJournal=e.target.closest('[data-delete-journal]');if(delJournal){const index=Number(delJournal.dataset.deleteJournal),entry=state.journal[index];try{if(window.JALUR_API?.getUser?.()&&entry?.id){await window.JALUR_API.request(`/journal/${encodeURIComponent(entry.id)}`,{method:"DELETE"});const saved=await window.JALUR_API.request("/journal");state.journal=saved.items||[];}else state.journal.splice(index,1);saveState();render();toast("Catatan dihapus.","info");}catch(err){toast(err.message||"Catatan gagal dihapus.","error");}return}
 if(e.target.id==="exportData"){const payload={app:"JALUR",version:1,exportedAt:new Date().toISOString(),state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=`jalur-cadangan-${new Date().toISOString().slice(0,10)}.json`;document.body.append(a);a.click();a.remove();URL.revokeObjectURL(url);toast("Cadangan data berhasil disiapkan.");return}
 if(e.target.id==="importData"){const f=$("#importDataFile");if(f)f.click();return}
 if(e.target.id==="addSubject"||e.target.id==="addSubjectEmpty")subjectForm();
 if(e.target.id==="importSample"){state.profile.subjects=[{name:"Matematika",semester:"Semester 1",year:state.profile.year,grade:86,source:"Data Contoh"},{name:"Bahasa Indonesia",semester:"Semester 1",year:state.profile.year,grade:88,source:"Data Contoh"},{name:"Bahasa Inggris",semester:"Semester 1",year:state.profile.year,grade:84,source:"Data Contoh"},{name:"Biologi",semester:"Semester 1",year:state.profile.year,grade:87,source:"Data Contoh"},{name:"Kimia",semester:"Semester 1",year:state.profile.year,grade:82,source:"Data Contoh"},{name:"Matematika",semester:"Semester 2",year:state.profile.year,grade:89,source:"Data Contoh"}];saveState();logActivity("Data Contoh akademik diimpor");render();toast("Data Contoh ditambahkan dengan label yang jelas.");}
 if(e.target.id==="resetExplorer"||e.target.id==="resetExplorerEmpty"){window.explorerQuery="";window.explorerScope="Semua hasil";window.explorerField="Semua bidang";window.explorerLevel="Semua jenjang";window.explorerProvince="Semua provinsi";window.explorerLimit=30;render()}
 if(e.target.id==="loadMorePrograms"){window.explorerLimit=(window.explorerLimit||30)+30;render()}
 if(e.target.id==="addCompare")openProgramPicker("compare");
 if(e.target.id==="pickMainProgram")openProgramPicker("main");
 if(e.target.id==="clearComparison"){if(confirm("Kosongkan semua program dari perbandingan? Catatan pribadi tidak dihapus.")){state.compared=[];saveState();render();toast("Perbandingan dikosongkan.","info")}}
 if(e.target.id==="saveNotes"){const selected=state.compared.map(programById).filter(Boolean);state.notes.comparisonChoices=state.notes.comparisonChoices||{};selected.forEach(p=>{const values=readChoices("comparison:"+p.id);state.notes.comparisonChoices[p.id]=values;state.notes[p.id]=values.join(" · ");});saveState();logActivity("Kriteria perbandingan disimpan");toast("Pilihan pertimbangan berhasil disimpan.");}
 if(e.target.id==="makePlan")navigate("Plan B Builder");
 if(e.target.id==="addAlternative")openProgramPicker("alternative");
 if(e.target.id==="clearMain"){state.mainChoice=null;saveState();render()}
 if(e.target.id==="printSummary")window.print();
 if(e.target.id==="resetSession"){if(confirm("Hapus semua data sesi dari browser ini? Tindakan ini tidak dapat dibatalkan.")){localStorage.removeItem(STORE_KEY);state=structuredClone(initialState);currentPage="Dashboard";$("#app").classList.add("hidden");$("#welcome").classList.remove("hidden");toast("Data sesi dihapus.","success")}}
});
if(state.settings.largeText)document.body.style.fontSize="17px";
if(state.settings.reduceMotion)document.documentElement.style.scrollBehavior="auto";

window.JALUR_SET_JOURNAL = items => { state.journal = Array.isArray(items) ? items : []; saveState(); render(); };
window.JALUR_GET_WORKSPACE = () => ({profile:state.profile,notes:state.notes,compared:state.compared,mainChoice:state.mainChoice,alternatives:state.alternatives,checked:state.checked,costPlans:state.costPlans,pathwayGroups:state.pathwayGroups,settings:state.settings});
window.JALUR_SET_WORKSPACE = workspace => { if(!workspace||typeof workspace!=="object")return; for(const key of ["profile","notes","compared","mainChoice","alternatives","checked","costPlans","pathwayGroups","settings"])if(Object.prototype.hasOwnProperty.call(workspace,key))state[key]=workspace[key]; saveState(); render(); };
window.JALUR_SET_ACTIVE_PAGE = page => { currentPage=page;state.currentPage=page;const label=PAGE_LABELS[page]||page;const crumb=$("#pageCrumb");if(crumb)crumb.textContent=label;$$("[data-page]").forEach(b=>b.classList.toggle("active",b.dataset.page===page));const primaryBottom=["Dashboard","Study Program Explorer","Decision Comparison","Plan B Builder"];$("#moreNav")?.classList.toggle("active",!primaryBottom.includes(page)); };
